/* ============================================================
   Interview notes: the whole regression process in plain words,
   rewritten for the selected variant with live numbers.
   NOTES.render(el, ctx) where ctx = { P, d, a, v, isBase, inf, S, cur }.
   ============================================================ */
const NOTES = (() => {
  const n = (v, d = 2) => num(v, d), pv = p => !isFinite(p) ? '—' : p < 0.001 ? 'below 0.001' : n(p, 3);

  /* what each assumption means, said simply */
  const ASSUME = {
    linearity: { rule: 'On average, y changes by the same amount for every one-unit step in x. The true relationship is a straight line (or a flat plane with several features).', why: 'The model can only draw straight lines. If the truth bends, the line is systematically wrong in some ranges, and its slope is an average of different effects.' },
    independence: { rule: 'Each row\'s error tells you nothing about any other row\'s error.', why: 'The standard error assumes every row is a fresh, independent piece of information. If rows share information, the model is more confident than it should be.' },
    homoscedasticity: { rule: 'The errors have the same spread everywhere: the scatter around the line is a band of even width.', why: 'The classical standard error uses one number for the noise. If the noise is bigger in some places, that one number is wrong, and so are the p-values and intervals.' },
    normality: { rule: 'The errors follow a bell curve.', why: 'This is only needed for exact small-sample t tests, F tests and prediction intervals. It is the least important assumption: with a few dozen rows the central limit theorem makes the tests approximately right anyway.' },
    multicollinearity: { rule: 'No feature can be predicted (almost) perfectly from the other features.', why: 'If two features move together, the data cannot say which one deserves the credit. The individual coefficients become unstable, or impossible to compute.' },
    exogeneity: { rule: 'The error is unrelated to x: nothing that is left out of the model moves together with x.', why: 'This is the assumption that makes the slope mean what we want it to mean. If it fails, the slope is biased, and more data does not fix it.' },
    /* data properties: not assumptions of the model, but properties of the data that decide what the model can learn */
    outliers: { rule: 'Every row follows the same pattern; no single row is far from the rest.', why: 'Least squares squares the errors, so one far-away row can pull the whole line toward itself.' },
    samplesize: { rule: 'There are many more rows than coefficients.', why: 'Each row is one equation. With few spare rows, the noise cannot be measured and every estimate swings from sample to sample.' },
    noise: { rule: 'The noise is small compared with the signal.', why: 'Noise sets the floor for every error and every uncertainty: SEs and test RMSE scale with σ.' },
    range: { rule: 'The observed x values cover the range where the model will be used.', why: 'The data only show the relationship where there are rows. Outside that range, or in a gap, the line is a guess.' },
    irrelevant: { rule: 'Every column carries information about y.', why: 'A useless column still gets a coefficient. It fits training noise, adds variance, and can look significant by chance.' },
    missing: { rule: 'Every value was recorded, or the values that are missing are missing for reasons unrelated to y.', why: 'Dropping incomplete rows is safe only when the reason for missingness does not depend on y itself.' },
    target: { rule: 'y is a continuous, unbounded measurement with roughly constant, bell-shaped noise.', why: 'A straight line with constant noise is the wrong shape for skewed, bounded or count targets: predictions leave the possible range and the SEs are off.' },
    categorical: { rule: 'Categories are encoded as 0/1 columns with one reference level, and every level has enough rows.', why: 'A category has no numeric order. One-hot encoding lets each level have its own shift; rare levels get unreliable coefficients.' },
    subgroups: { rule: 'All rows come from one population with one relationship, or the groups are in the model.', why: 'A pooled line averages different relationships and can describe none of them, or even get the sign wrong.' },
    shift: { rule: 'New data come from the same place as the training data.', why: 'The test score only predicts real performance if the test rows look like the rows the model will meet.' },
    leakage: { rule: 'Nothing the model sees uses information that would not be available at prediction time.', why: 'Leakage makes the test score look better than real use will ever be.' },
    /* feature engineering: choices made in step 5, learned on the training rows */
    scaling: { rule: 'Put features on comparable scales, using statistics from the training rows.', why: 'Least-squares predictions do not change, but gradient descent, penalties and the condition number do.' },
    xtransform: { rule: 'Transform a feature so that y is roughly a straight line in it.', why: 'A straight-line model can only fit a straight relationship; the right transform straightens a curve.' },
    ytransform: { rule: 'Transform y so that the relationship is straight and the spread even.', why: 'Multiplicative, skewed targets break linearity, constant variance and normality at once; a log often fixes all three.' },
    degree: { rule: 'Add powers of x to let the line bend: enough to follow the truth, not so many that it follows the noise.', why: 'Too low underfits, too high overfits; the degree is the classic bias–variance dial.' },
    interactions: { rule: 'Add x₁·x₂ when the effect of one feature depends on another.', why: 'Without it, the model forces one slope for x₁ at every value of x₂.' },
    splines: { rule: 'Let the slope change at chosen knots.', why: 'Piecewise lines follow curves while staying interpretable and stable at the edges.' },
    binning: { rule: 'Cut a numeric feature into intervals only when the relationship is step-like.', why: 'Bins can fit any shape between edges but throw away the information inside each bin.' },
    encoding: { rule: 'Turn a text category into numbers without inventing an order: one-hot with one level dropped, or target encoding learned on the training rows.', why: 'The encoding decides how many columns a category becomes and what each coefficient means.' },
    centering: { rule: 'Centre a feature before taking powers or products of it.', why: 'It removes artificial collinearity and makes the intercept and lower-order terms meaningful.' },
    selection: { rule: 'Keep the columns that carry information, choosing them with the training rows only.', why: 'Noise columns add variance; but every selection method can also drop useful columns, and p-values after selection are too optimistic.' },
    /* model formulation: which model, and which rule for its weights */
    intercept: { rule: 'Include an intercept unless theory forces the line through (0, 0).', why: 'Without it, the slope has to absorb the level of y, and residuals no longer average 0.' },
    modeltype: { rule: 'Match the model to the shape of the mean and to the structure of the errors.', why: 'Too simple a mean biases every coefficient; ignoring unequal or correlated errors wastes precision and breaks the standard errors.' },
    robust: { rule: 'When a few rows are badly wrong, use a loss or estimator that cannot be dragged by them.', why: 'The squared loss gives a row twice as far away four times the pull, so one gross outlier can tilt the whole line.' },
    regularisation: { rule: 'Add a price on large weights when there are many, correlated or weak features.', why: 'A small amount of bias buys a large drop in variance, so predictions on new rows improve.' },
    lambda: { rule: 'Choose the penalty strength λ by cross-validation on the training rows.', why: 'λ = 0 is OLS (high variance); a huge λ predicts the mean (high bias); the best λ is in between.' },
    alpha: { rule: 'Mix the L1 and L2 penalties: α = 1 selects features, α = 0 shares weight among correlated ones.', why: 'Correlated groups make pure lasso pick one member at random; some L2 keeps the group together.' },
    penalisebias: { rule: 'Do not penalise the intercept.', why: 'The intercept only sets the level of y; shrinking it toward 0 biases every prediction by an amount that depends on the units of y.' },
    lossfn: { rule: 'Choose the loss to match what you want to predict and how the errors behave: squared for the mean, absolute for the median, pinball for a quantile, Huber or log-cosh for a robust centre.', why: 'The loss decides which line is "best"; with skewed or heavy-tailed errors the choices give visibly different lines.' },
    penalty: { rule: 'Add a penalty term to the loss when the weights need to be kept small: L2 to shrink, L1 to select, both for correlated groups.', why: 'The penalty trades a little training error for stability on new rows.' },
    metric: { rule: 'Pick the metric from the cost of errors: RMSE when big errors hurt most, MAE when every unit costs the same, MAPE only when y stays well away from 0, R² to compare with the mean, AIC/BIC to compare models on the training data.', why: 'Different metrics can rank the same models differently.' },
    traintest: { rule: 'Compare training and test error: a big gap means overfitting, both high means underfitting.', why: 'The training error alone always rewards more flexibility.' },
    learningcurve: { rule: 'Plot training and validation error against the training size to decide whether more data or a different model will help.', why: 'High bias plateaus early; high variance closes slowly with more data.' },
    validationcurve: { rule: 'Scan one complexity setting with cross-validation and take the bottom of the U.', why: 'The training error always improves with complexity; only held-out error shows the trade-off.' },
    biasvariance: { rule: 'Expected test error = bias² + variance + noise; flexibility lowers bias and raises variance.', why: 'It explains under- and overfitting, and why regularisation and more data help.' },
    split: { rule: 'Hold out enough rows that the test score is stable, but keep enough to fit well: 70–80% for training is typical; with little data, use cross-validation.', why: 'The test score is itself an estimate with an error of about RMSE/√(2N_test).' },
    cv: { rule: 'Estimate the error with cross-validation on the training rows; respect time order; nest it when it also chooses the model.', why: 'One split is noisy; ignoring time order leaks the future; choosing and scoring on the same folds is optimistic.' },
    seed: { rule: 'Fix the seed for reproducibility, but vary it (or cross-validate) to see how much the result depends on the split.', why: 'One seed is one draw of the split: its score is not the score.' },
    solver: { rule: 'Any correct solver gives the least-squares weights; choose by size and conditioning: QR or the SVD for accuracy, Cholesky for speed, iterative methods for huge or sparse data.', why: 'Forming X̃ᵀX̃ squares the condition number; with nearly collinear features that loses digits.' },
    gdtype: { rule: 'Use mini-batches in practice: cheap steps, vectorised, with noise that a decaying η controls.', why: 'Full-batch gradients are exact but expensive; single-row gradients are cheap but noisy.' },
    lr: { rule: 'Keep η below 2/λ_max of the curvature, and as large as is stable.', why: 'Too small crawls, near the limit zig-zags, above it diverges.' },
    schedule: { rule: 'Decay the learning rate when the gradient is noisy (SGD, mini-batch).', why: 'With a constant η, SGD keeps bouncing around the minimum.' },
    optimiser: { rule: 'Momentum-type methods speed up long narrow valleys; adaptive methods (RMSProp, Adam) equalise the step size per weight.', why: 'Plain gradient descent is slow when the curvature differs a lot between directions.' },
    init: { rule: 'For least squares the start does not matter for the answer, only for the time it takes.', why: 'The loss is convex: one minimum, reached from anywhere.' },
    stopping: { rule: 'Stop on a tolerance (gradient or loss change), or on validation loss when early stopping is used as regularisation.', why: 'A fixed budget may stop too early or waste time; tolerances adapt to the problem.' },
    scalegd: { rule: 'Standardise the features before gradient descent.', why: 'Very different scales make the loss bowl a narrow valley, and gradient descent crawls along it.' },
    otherforms: { rule: 'Other ways to tame many correlated features: fit on a few components, or put a prior on the weights.', why: 'They trade a little bias for stability, like ridge, and each gives something extra: fewer dimensions, or a full uncertainty for every weight.' },
  };

  /* plain-language card per variant */
  const V = {

    /* ---------- feature engineering ---------- */
    scnone: { what: 'No scaling: x₁ (0–10) and x₂ (thousands) are used as they are.', line: 'Least-squares predictions do not depend on scaling, but κ and gradient descent do.' },
    scstd: { what: 'Standardisation: (x − mean) / sd on the training rows.', real: 'The default before gradient descent, ridge, lasso, PCA.', see: 'Every feature has mean 0 and sd 1; κ is small.', breaks: 'Nothing; an extreme value inflates the sd a little.', fine: 'Predictions identical to no scaling.', detect: '—', fix: 'StandardScaler inside a Pipeline.', line: 'Standardising changes the units of w̃, not the predictions.' },
    scminmax: { what: 'Min–max scaling into [0, 1].', real: 'Neural-network inputs, image pixels.', see: 'One very large x₂ squeezes all the others near 0.', breaks: 'Robustness: one extreme value defines the range.', fine: 'Predictions.', detect: 'Check the scaled histogram.', fix: 'Use robust scaling or clip extremes.', line: 'Min–max scaling is ruined by a single extreme value.' },
    scrobust: { what: 'Robust scaling with the median and the IQR.', real: 'Data with outliers or heavy tails.', see: 'The ordinary rows keep a normal spread despite the extreme x₂.', breaks: 'Nothing.', fine: 'Predictions.', detect: '—', fix: 'RobustScaler.', line: 'Median and IQR ignore extremes, so robust scaling keeps the bulk of the data spread out.' },
    xtnone: { what: 'x used raw although y rises with ln x.', line: 'A curved residual plot says the feature needs a transform.' },
    xtlog: { what: 'x replaced by ln x.', real: 'Income, population, prices, any feature where ratios matter.', see: 'The scatter of y against ln x is straight; residuals lose their bend.', breaks: 'Needs x > 0.', fine: 'Everything else.', detect: 'Skewed x, curved residuals.', fix: 'np.log or FunctionTransformer(np.log).', line: 'With ln x, a 1% increase in x changes y by about w/100.' },
    xtsqrt: { what: 'x replaced by √x.', real: 'Counts, areas.', see: 'A partial straightening.', breaks: 'Less effective than the log for strong skew.', fine: 'Works for x ≥ 0.', detect: '—', fix: 'np.sqrt.', line: 'The square root is a milder log.' },
    xtboxcox: { what: 'Box-Cox transform of x with λ chosen by maximum likelihood.', real: 'Any positive, skewed feature.', see: 'λ near 0 here, so close to the log.', breaks: 'Needs x > 0; λ must come from the training rows.', fine: 'Chooses the power automatically.', detect: '—', fix: "PowerTransformer(method='box-cox').", line: 'Box-Cox searches the power family for the most bell-shaped version of x.' },
    xtyj: { what: 'Yeo-Johnson transform of x.', real: 'Skewed features that can be zero or negative.', see: 'Similar to Box-Cox on positive data.', breaks: 'Harder to interpret.', fine: 'Handles any sign.', detect: '—', fix: "PowerTransformer(method='yeo-johnson').", line: 'Yeo-Johnson is Box-Cox for any real values.' },
    ytnone: { what: 'An exponential, skewed y modelled as it is.', line: 'Residuals that curve and fan out suggest transforming y.' },
    ytlog: { what: 'The model is fitted to ln y.', real: 'Prices, incomes, sales, durations.', see: 'Straight, evenly spread residuals on the log scale.', breaks: 'Predictions must be turned back with e^ẑ, which gives the median, not the mean.', fine: 'Linearity, constant variance and normality at once.', detect: 'Skewed y, funnel-shaped residuals.', fix: 'TransformedTargetRegressor(func=np.log, inverse_func=np.exp).', line: 'With ln y, each unit of x multiplies y by e^w.' },
    ytboxcox: { what: 'The model is fitted to the Box-Cox transform of y.', real: 'Positive targets of unknown skew.', see: 'λ chosen from the training y.', breaks: 'Interpretation is harder than with the log.', fine: 'Chooses the power automatically.', detect: '—', fix: "PowerTransformer(method='box-cox') on y.", line: 'Box-Cox on y picks the power that best normalises the target.' },
    deg1: { what: 'A straight line through an S-shaped truth.', line: 'Degree 1 underfits a curve: high bias.' },
    deg2: { what: 'A parabola.', real: 'Gentle curvature.', see: 'Better, but cannot follow both bends.', breaks: 'Still some bias.', fine: 'Stable.', detect: 'RESET, residual plot.', fix: 'Raise the degree or use splines.', line: 'Each extra power adds one bend.' },
    deg3: { what: 'A cubic: the shape of the truth.', real: 'Smooth S-shaped relationships.', see: 'Residuals look random; test error is lowest.', breaks: 'Nothing.', fine: 'Everything.', detect: '—', fix: 'Choose the degree by cross-validation.', line: 'The right degree balances bias and variance.' },
    deg5: { what: 'Degree 5: more flexible than needed.', real: '—', see: 'Small wiggles; slightly worse test error.', breaks: 'Variance grows.', fine: 'Still reasonable.', detect: 'Validation curve.', fix: 'Lower degree or regularise.', line: 'Extra flexibility starts to fit noise.' },
    deg10: { what: 'Degree 10: overfitting.', real: 'Fitting a high-order curve to a small sample.', see: 'Wild swings near the edges; train error low, test error high; κ astronomical.', breaks: 'Generalisation and coefficient stability.', fine: 'Training error.', detect: 'Train vs test error; validation curve.', fix: 'Lower degree, splines, or ridge.', line: 'High-degree polynomials overfit and explode at the edges.' },
    intnone: { what: 'The truth has an interaction, the model does not.', line: 'Without x₁·x₂, the model forces one slope of x₁ everywhere.' },
    intx: { what: 'An x₁·x₂ column is added.', real: 'Advertising that works better in high season; a drug whose effect depends on dose and age.', see: 'Test error drops; w₁₂ ≈ 0.3.', breaks: 'w₁ alone no longer means "the effect of x₁".', fine: 'Predictions.', detect: 'Residuals that twist across x₁ and x₂; partial F-test for the term.', fix: 'PolynomialFeatures(interaction_only=True) or a formula y ~ x1 * x2.', line: 'With an interaction, the slope of x₁ is w₁ + w₁₂·x₂.' },
    spnone: { what: 'One straight line through a saturating curve.', line: 'A curve needs either a transform, a polynomial or splines.' },
    sp1: { what: 'One knot at x = 5.', real: 'A policy threshold, a capacity limit.', see: 'Two straight pieces joined at 5.', breaks: 'The knot position is a guess.', fine: 'Interpretable slopes.', detect: '—', fix: 'Choose knots from domain knowledge or quantiles.', line: 'A hinge weight is the change in slope at its knot.' },
    spmany: { what: 'Three knots at 2.5, 5, 7.5.', real: 'Smooth non-linear effects (age, temperature).', see: 'Four pieces following the curve.', breaks: 'More knots, more variance.', fine: 'Stable at the edges, unlike high-degree polynomials.', detect: '—', fix: 'SplineTransformer with knots at quantiles.', line: 'Splines bend locally; polynomials bend everywhere.' },
    binnone: { what: 'x used as a number.', line: 'Binning is a choice, not a default.' },
    binwidth: { what: '5 equal-width bins.', real: 'Age groups 0–20, 20–40, …', see: 'Uneven bin counts because x is bunched; a staircase fit.', breaks: 'Information inside each bin; nearly empty bins are noisy.', fine: 'Captures the jump.', detect: 'Rows per bin.', fix: "KBinsDiscretizer(strategy='uniform').", line: 'Equal-width bins can be nearly empty when x is skewed.' },
    binquant: { what: '5 quantile bins.', real: 'Income quintiles.', see: 'Even bin counts.', breaks: 'Information inside each bin.', fine: 'Every bin estimable.', detect: '—', fix: "KBinsDiscretizer(strategy='quantile').", line: 'Quantile bins give each bin the same number of rows.' },
    encoh: { what: 'One-hot encoding with one level dropped.', line: 'k levels → k − 1 dummy columns; each coefficient is a gap from the reference.' },
    encall: { what: 'All four dummies kept with an intercept.', real: 'pd.get_dummies without drop_first.', see: 'rank(X̃) < p; a zero eigenvalue; undefined SEs.', breaks: 'Uniqueness of the coefficients.', fine: 'Predictions (with a pseudo-inverse).', detect: 'Rank, VIF.', fix: 'Drop one level.', line: 'With an intercept, keeping all dummies is the dummy-variable trap.' },
    encord: { what: 'Ordinal codes 0–3.', real: 'Encoding unordered labels as integers by mistake.', see: 'One slope per code step; poor fit when the level effects are not in that order.', breaks: 'The model forces an order and equal steps.', fine: 'Genuinely ordered categories with even steps.', detect: 'Compare with one-hot.', fix: 'One-hot or target encoding.', line: 'Integer codes invent an order that unordered categories do not have.' },
    enctarget: { what: 'Target encoding: each level → its mean y in the training rows.', real: 'High-cardinality categories (zip code, product ID).', see: 'One column; a good fit.', breaks: 'Leakage if computed on all rows; noisy for rare levels.', fine: 'Compact.', detect: '—', fix: 'TargetEncoder with cross-fitting and smoothing.', line: 'Target encoding is powerful but must be learned on training folds only.' },
    cenraw: { what: 'x and x² used raw, with x far from 0.', line: 'Raw x and x² are almost collinear when x is far from 0.' },
    cencent: { what: 'x centred before squaring.', real: 'Polynomial and interaction models.', see: 'VIF near 1, small SE for the linear term, a meaningful intercept.', breaks: 'Nothing.', fine: 'Predictions identical.', detect: 'VIF of x and x².', fix: 'x − x̄ (training mean) before powers or products.', line: 'Centring removes artificial collinearity without changing predictions.' },
    selall: { what: 'All 10 candidate columns.', line: 'With noise columns, the full model over-fits a little and some noise looks significant.' },
    selfwd: { what: 'Forward selection by p-value.', real: 'Classic exploratory modelling.', see: 'Columns added one at a time.', breaks: 'Greedy: may miss combinations; p-values afterwards are biased.', fine: 'Simple.', detect: '—', fix: 'Prefer cross-validated selection or lasso.', line: 'Forward selection is greedy and its p-values ignore the search.' },
    selbwd: { what: 'Backward elimination by p-value.', real: 'Trimming a full model.', see: 'Columns removed one at a time.', breaks: 'Needs N > p to start; same p-value bias.', fine: 'Considers all columns together at the start.', detect: '—', fix: 'Cross-validated selection.', line: 'Backward elimination starts from everything and peels off the weakest.' },
    selstep: { what: 'Stepwise selection.', real: 'Many statistics packages.', see: 'Adds and re-checks.', breaks: 'Same issues as forward.', fine: 'Can remove a column made redundant later.', detect: '—', fix: '—', line: 'Stepwise is forward selection with second thoughts.' },
    sellasso: { what: 'Lasso with λ from cross-validation.', real: 'High-dimensional data.', see: 'Noise columns shrunk to exactly 0.', breaks: 'With correlated columns it picks one arbitrarily.', fine: 'Selection and shrinkage in one convex problem.', detect: '—', fix: 'LassoCV.', line: 'The L1 penalty sets weak coefficients exactly to zero.' },
    selvif: { what: 'Drop high-VIF columns.', real: 'Removing redundant features.', see: 'x₅ (the near-copy of x₁) or x₁ removed.', breaks: 'Never looks at y, so it keeps noise columns.', fine: 'Removes redundancy.', detect: '—', fix: 'Combine with a relevance check.', line: 'VIF selection removes redundancy, not irrelevance.' },
    selp: { what: 'One-shot p-value filter.', real: 'Quick screening.', see: 'Everything with p > 0.05 dropped at once.', breaks: 'Correlated columns can all look insignificant together.', fine: 'Fast.', detect: '—', fix: 'Iterative or cross-validated selection.', line: 'Dropping all non-significant columns at once can throw out useful, correlated ones.' },
    /* ---------- model formulation ---------- */
    intin: { what: 'The model has an intercept: ŷ = b + w·x.', line: 'With an intercept the residuals average 0 and the slope is not distorted by the level of y.' },
    intorigin: { what: 'The intercept is forced to 0: ŷ = w·x, on data whose true intercept is 6.', real: 'Physical laws (distance = speed × time), cost per unit with no fixed cost.', see: 'The fitted line pivots around (0, 0); it is too steep, overshoots at large x, undershoots at small x; residuals do not average 0.', breaks: 'The slope is biased whenever the true intercept is not 0; R² is reported uncentred and looks misleadingly high.', fine: 'Nothing, unless y really is 0 at x = 0.', detect: 'Fit with an intercept and test whether it is 0 (its t statistic).', fix: 'Keep the intercept (fit_intercept=True), and centre x if you want it interpretable.', line: 'Dropping the intercept is a strong claim about the data; it biases the slope if the claim is false.' },
    mtsimple: { what: 'Only x₁, for data that depend on x₁, x₂ and x₁².', real: 'Price on size only, when location also matters.', see: 'Residuals curved in x₁ and correlated with x₂.', breaks: 'Omitted x₂ biases the x₁ slope if x₁ and x₂ are correlated; the missing curve biases everything.', fine: 'A rough summary of the x₁ trend.', detect: 'Residual plots against x₁ and the left-out features.', fix: 'Add the missing features and the curve.', line: 'A model that leaves out a relevant, correlated feature has biased slopes.' },
    mtmultiple: { what: 'x₁ and x₂, as straight lines.', real: 'The standard multiple regression.', see: 'Residuals still bend in x₁.', breaks: 'The missing x₁² term: mild curvature bias.', fine: 'The x₂ effect, and much better predictions than simple.', detect: 'A residual vs x₁ plot or a RESET test.', fix: 'Add x₁².', line: 'Multiple regression holds the other features fixed; it does not fix a wrong shape.' },
    mtpoly: { what: 'x₁, x₂ and x₁²: the right shape for the mean.', real: 'Diminishing or accelerating effects.', see: 'Residuals without a pattern in x₁, but their spread grows with x₁ and neighbouring rows are correlated.', breaks: 'The classical standard errors (unequal and correlated errors).', fine: 'Unbiased coefficients and good predictions.', detect: 'Breusch–Pagan and Durbin–Watson (step 11).', fix: 'Robust SEs, or WLS / GLS for efficiency.', line: 'A polynomial is still linear regression: linear in the weights.' },
    mtwls: { what: 'The polynomial model with each row weighted by 1 / its estimated error variance.', real: 'Averages over groups of different sizes, measurement devices of known precision, spending that varies more for high incomes.', see: 'Nearly the same line, with smaller standard errors; noisy rows count less.', breaks: 'If the variance model is wrong, WLS can be less precise than OLS with robust SEs.', fine: 'Unbiased whatever the weights, as long as the mean is right.', detect: 'Residual spread vs x (step 11, Breusch–Pagan).', fix: 'statsmodels WLS with weights = 1/σ̂², from a model of the residual variance.', line: 'WLS is OLS on rows rescaled so every error has the same variance: it is BLUE when the weights are right.' },
    mtgls: { what: 'The polynomial model, refitted after removing the AR(1) correlation of neighbouring errors (Prais–Winsten).', real: 'Time series: sales, temperatures, any rows in time order.', see: 'Coefficients close to OLS, but honest (larger) standard errors and a Durbin–Watson near 2 after the transform.', breaks: 'Nothing if the errors are AR(1); wrong if the correlation has another form.', fine: 'Unbiased coefficients.', detect: 'Durbin–Watson or the lag-1 residual correlation.', fix: 'statsmodels GLSAR, or Newey–West SEs if only inference matters.', line: 'GLS transforms the model so its errors are independent, then applies OLS.' },
    rbols: { what: 'Least squares on data with a few gross outliers.', real: 'Data-entry errors, sensor glitches, fraud rows.', see: 'The line tilts toward the outliers; large Cook’s distances.', breaks: 'The slope, the intercept and every prediction near the outliers.', fine: 'Nothing is broken if the outliers are real and important.', detect: 'Residual and leverage plots, Cook’s distance (step 10).', fix: 'Check the rows; use a robust method if they are errors.', line: 'OLS has a breakdown point of 0: one bad row can move it anywhere.' },
    rbhuber: { what: 'Huber loss: squared for small residuals, linear for large ones.', real: 'The default robust regression (statsmodels RLM, scikit-learn HuberRegressor).', see: 'A line through the bulk of the data; outliers get weights well below 1.', breaks: 'Bad rows with high leverage can still pull it (it is robust in y, not in x).', fine: 'Almost as precise as OLS when there are no outliers.', detect: '—', fix: 'Tune c (1.345 gives 95% efficiency under normal errors).', line: 'Huber gives a large residual a constant pull instead of a growing one.' },
    rbransac: { what: 'Many random two-row lines; keep the one with the most inliers; refit on those.', real: 'Computer vision (fitting lines and planes with many bad matches).', see: 'The outliers are ignored completely.', breaks: 'Results depend on the random draws and the inlier threshold.', fine: 'Handles up to about half the data being bad.', detect: '—', fix: 'Set the threshold from the noise scale; more trials.', line: 'RANSAC finds the consensus line and ignores everything else.' },
    rbtheil: { what: 'The median of the slopes of all pairs of rows.', real: 'Trends in environmental and climate data.', see: 'A line through the bulk of the data.', breaks: 'Slow for large N (N² pairs); one feature only in its classic form.', fine: 'Robust to about 29% bad rows, with no tuning.', detect: '—', fix: 'scipy.stats.theilslopes or scikit-learn TheilSenRegressor.', line: 'Theil–Sen is a median of slopes, so extreme slopes do not move it.' },
    rbquant: { what: 'Minimise the sum of absolute errors: the line through the conditional median.', real: 'Medians of house prices or incomes; other quantiles for risk (90th percentile of delivery time).', see: 'Half the rows above the line, half below; outliers in y barely matter.', breaks: 'Less precise than OLS under normal errors; still pulled by high-leverage rows.', fine: 'Robust to outliers in y.', detect: '—', fix: 'statsmodels QuantReg (q = 0.5) or scikit-learn QuantileRegressor.', line: 'Median regression is to OLS what the median is to the mean.' },
    rgnone: { what: 'Least squares on 8 correlated features, only 4 of which matter.', real: 'Many related measurements: survey items, sensor arrays, overlapping financial ratios.', see: 'Large, unstable weights with opposite signs on correlated features; a test error above the training error.', breaks: 'Variance: the weights change a lot from sample to sample.', fine: 'Unbiased, and fine when N is much larger than p.', detect: 'VIF, κ, and the gap between training and test error.', fix: 'Ridge, lasso or elastic net with λ by CV.', line: 'With many correlated features OLS is unbiased but very variable.' },
    rgridge: { what: 'Ridge: add λ·Σw̃² to the loss; λ by 5-fold CV.', real: 'Many correlated predictors; the default stabiliser.', see: 'Every weight smaller than OLS, none exactly 0; correlated features share the weight.', breaks: 'A small bias toward 0; the weights are no longer unbiased estimates.', fine: 'Always has a unique solution, even when p > N.', detect: '—', fix: 'RidgeCV inside a Pipeline with StandardScaler.', line: 'Ridge shrinks along the directions the data cannot pin down.' },
    rglasso: { what: 'Lasso: add λ·Σ|w̃|; λ by CV.', real: 'Many candidate features, few that matter: genomics, marketing attributions.', see: 'Some weights exactly 0; the rest shrunk.', breaks: 'With correlated features it keeps one member of a group and drops the others somewhat arbitrarily.', fine: 'Selection and fitting in one step.', detect: '—', fix: 'LassoCV; elastic net if features are correlated.', line: 'The L1 corner at 0 is what makes lasso select features.' },
    rgenet: { what: 'Elastic net with α = 0.5: half lasso, half ridge.', real: 'Correlated groups of useful features.', see: 'Zeros like lasso, but correlated features keep similar weights.', breaks: 'Two tuning parameters.', fine: 'Selection that is more stable than lasso.', detect: '—', fix: 'ElasticNetCV over λ and α.', line: 'Elastic net = lasso’s sparsity + ridge’s grouping.' },
    lam0: { what: 'Ridge with λ = 0.', real: 'No penalty at all.', see: 'Exactly the OLS weights.', breaks: 'Nothing compared with OLS; the same high variance.', fine: 'Unbiased.', detect: '—', fix: 'Choose λ by CV.', line: 'Ridge with λ = 0 is OLS.' },
    lamsmall: { what: 'Ridge with λ = 0.1.', real: 'A token penalty, often used just to make XᵀX invertible.', see: 'Weights barely different from OLS.', breaks: 'Too little shrinkage to reduce the variance much.', fine: 'Numerical stability.', detect: 'The CV curve: error still falling as λ grows.', fix: 'Increase λ toward the CV choice.', line: 'A tiny λ fixes invertibility, not variance.' },
    lamcv: { what: 'Ridge with the λ of lowest 5-fold CV error.', real: 'Standard practice (RidgeCV, GridSearchCV).', see: 'The test error is about the lowest of the five λ variants.', breaks: 'The CV choice is itself noisy; the 1-SE rule picks a simpler model.', fine: 'The best bias–variance trade-off the data can find.', detect: '—', fix: '—', line: 'Choose λ by cross-validation on training rows only, never on the test rows.' },
    lamlarge: { what: 'Ridge with λ = 300.', real: 'A penalty chosen too strong.', see: 'All weights clearly shrunk; the fit is flatter than the data.', breaks: 'Bias: the model underfits.', fine: 'Very stable weights.', detect: 'The CV curve rises again at large λ.', fix: 'Lower λ.', line: 'Too much λ trades variance for too much bias.' },
    lamhuge: { what: 'Ridge with λ = 30 000.', real: 'An extreme penalty.', see: 'Every weight nearly 0; predictions are about the mean of y.', breaks: 'Almost everything: the model ignores the features.', fine: 'The intercept, which is not penalised, still gets the mean right.', detect: 'Training R² near 0.', fix: 'Lower λ.', line: 'As λ → ∞, ridge predicts the mean.' },
    alridge: { what: 'Elastic net with α = 0: pure ridge.', real: '—', see: 'No zeros; correlated features share weight.', breaks: 'No feature selection.', fine: 'Stable.', detect: '—', fix: '—', line: 'α = 0 is ridge.' },
    albal: { what: 'α = 0.5.', real: 'A common default for correlated groups.', see: 'Some zeros, grouped weights.', breaks: '—', fine: 'Both selection and stability.', detect: '—', fix: 'Tune α by CV too.', line: 'α sets the mix between the L1 and L2 penalties.' },
    allasso: { what: 'α = 1: pure lasso.', real: '—', see: 'The most zeros; one feature per correlated group.', breaks: 'Unstable choice within correlated groups.', fine: 'The sparsest model.', detect: '—', fix: '—', line: 'α = 1 is lasso.' },
    pbno: { what: 'Ridge (λ = 10) with the intercept left free.', line: 'The intercept is not penalised: it absorbs the mean of y, about 60, without any cost.' },
    pbyes: { what: 'The same ridge, but the intercept is shrunk toward 0 too.', real: 'A ridge written by hand with λI instead of λD, or a design matrix with a column of 1s passed to a solver that penalises every column.', see: 'Every prediction biased toward 0 by about λ/(N + λ) of the mean of y; the slopes absorb some of the level.', breaks: 'The predictions, by a bias that depends on the units of y (it would vanish if y were centred).', fine: 'Nothing gains from it.', detect: 'Mean residual ≠ 0 on the training rows.', fix: 'Penalise the slopes only (scikit-learn does this when fit_intercept=True), or centre y.', line: 'Never penalise the intercept: the penalty should be on complexity, not on the level of y.' },
    lfmse: { what: 'Mean squared error on errors with a long upward tail.', line: 'Squared loss estimates the conditional mean, so a long tail drags the line toward it.' },
    lfmae: { what: 'Mean absolute error: Σ|y − ŷ|.', real: 'Delivery times, prices and other skewed targets where a typical value matters more than the average.', see: 'A line through the bulk of the data, half the rows above, half below.', breaks: 'No closed form; less efficient than MSE when errors are normal; not differentiable at 0.', fine: 'Robust to outliers in y.', detect: '—', fix: 'statsmodels QuantReg(q = 0.5), sklearn QuantileRegressor.', line: 'Absolute loss → median, squared loss → mean.' },
    lfhuber: { what: 'Huber loss with c = 1.345 robust standard deviations.', real: 'The usual compromise when a few rows are bad.', see: 'A line close to the MAE line, but smoother; the tail rows get weights below 1.', breaks: 'Needs a scale estimate and a constant c.', fine: 'About 95% as efficient as OLS under normal errors.', detect: '—', fix: 'HuberRegressor, statsmodels RLM.', line: 'Huber is squared loss near 0 and absolute loss in the tails.' },
    lfquant: { what: 'Pinball loss with q = 0.9.', real: 'Planning for the worst 10%: delivery promises, server capacity, flood levels.', see: 'A line above most of the data: about 10% of the rows above it.', breaks: 'It is not a model of the mean; separate quantile lines can cross.', fine: 'No assumption about the error distribution.', detect: '—', fix: 'QuantReg(q = 0.9); LightGBM objective="quantile".', line: 'Pinball loss with q estimates the q-th quantile of y given x.' },
    lflogcosh: { what: 'Log-cosh loss: ln(cosh e).', real: 'Smooth robust loss in gradient-boosting and neural-network regression.', see: 'A line between the MSE and the MAE lines.', breaks: 'Its switch from squared to absolute is at |e| ≈ 1 in the units of y, so it depends on the scale of y.', fine: 'Differentiable everywhere, so any gradient method works.', detect: '—', fix: 'scipy.optimize.minimize, XGBoost reg:pseudohubererror (a close cousin).', line: 'Log-cosh is a smooth Huber with no tuning constant.' },
    pnnone: { what: 'No penalty: the loss is only the squared error.', line: 'Without a penalty, correlated features give large, unstable weights.' },
    pnl2: { what: 'L2 penalty λΣw̃² (ridge), λ by CV.', real: 'Correlated predictors; the default stabiliser.', see: 'Every weight smaller; correlated features share weight; none exactly 0.', breaks: 'Small bias toward 0.', fine: 'Closed form: (X̃ᵀX̃ + λD)w̃ = X̃ᵀy.', detect: '—', fix: 'RidgeCV.', line: 'L2 shrinks every weight smoothly.' },
    pnl1: { what: 'L1 penalty λΣ|w̃| (lasso), λ by CV.', real: 'Many candidate features, few that matter.', see: 'Some weights exactly 0.', breaks: 'Unstable choice among correlated features.', fine: 'Selection and shrinkage in one fit.', detect: '—', fix: 'LassoCV.', line: 'The L1 corner at 0 produces exact zeros.' },
    pnl1l2: { what: 'L1 + L2 penalty (elastic net, α = 0.5), λ by CV.', real: 'Correlated groups of useful features.', see: 'Some zeros, grouped weights.', breaks: 'Two tuning parameters.', fine: 'Sparser than ridge, more stable than lasso.', detect: '—', fix: 'ElasticNetCV.', line: 'Elastic net combines L1 sparsity with L2 grouping.' },
    mtmse: { what: 'Mean squared error on the test rows.', line: 'MSE is the average squared error; its units are y².' },
    mtrmse: { what: 'Root mean squared error.', real: 'The default regression score.', see: 'The same ranking as MSE, in the units of y.', breaks: 'Sensitive to a few large errors.', fine: 'Easy to read.', detect: '—', fix: '—', line: 'RMSE is a typical error size in the units of y.' },
    mtmae: { what: 'Mean absolute error.', real: 'Forecasting, pricing.', see: 'Smaller than RMSE when a few errors are large.', breaks: 'Not differentiable at 0 as a loss.', fine: 'Robust to outliers.', detect: '—', fix: '—', line: 'MAE weighs every unit of error equally.' },
    mtmape: { what: 'Mean absolute percentage error.', real: 'Business reporting ("we are 8% off").', see: 'A percentage, comparable across scales.', breaks: 'Explodes near y = 0; asymmetric.', fine: 'Easy to communicate.', detect: '—', fix: 'Use sMAPE or MAE when y can be near 0.', line: 'MAPE is relative error; never use it when y can be 0.' },
    mtr2: { what: 'R² on the test rows.', real: 'Model summaries.', see: 'Between −∞ and 1; negative means worse than the mean.', breaks: 'Depends on the spread of y in the test set.', fine: 'Unit-free.', detect: '—', fix: '—', line: 'R² = 1 − SSE/SST: the share of variance explained.' },
    mtadjr2: { what: 'Adjusted R² on the training rows.', real: 'Comparing nested regressions.', see: 'Rises only if a term helps more than chance.', breaks: 'A weak penalty.', fine: 'No test set needed.', detect: '—', fix: '—', line: 'Adjusted R² penalises extra coefficients.' },
    mtaic: { what: 'AIC on the training rows.', real: 'Model selection in statistics.', see: 'Lower is better; it picks a moderately flexible model.', breaks: 'Assumes the likelihood (normal errors).', fine: 'Approximates out-of-sample fit.', detect: '—', fix: '—', line: 'AIC = −2 log L + 2p.' },
    mtbic: { what: 'BIC on the training rows.', real: 'When a simple, true model is wanted.', see: 'Prefers simpler models than AIC.', breaks: 'Can underfit with little data.', fine: 'Consistent model selection.', detect: '—', fix: '—', line: 'BIC = −2 log L + p ln n.' },
    ttgood: { what: 'A model with the right flexibility.', line: 'Train and test errors both low and close: a good fit.' },
    ttover: { what: 'Degree 10 on 16 rows.', real: 'Too many features or too flexible a model for the data.', see: 'Training error near 0, test error large; wild curve between points.', breaks: 'Predictions on new rows.', fine: 'Nothing useful.', detect: 'Test (or CV) error far above training error.', fix: 'Simpler model, regularisation, more data.', line: 'Overfitting: the model learned the noise.' },
    ttunder: { what: 'A straight line through a curve.', real: 'A model missing important features or shape.', see: 'Training and test errors both high and close.', breaks: 'Accuracy everywhere.', fine: 'Stable.', detect: 'Patterned residuals; high training error.', fix: 'More flexible model.', line: 'Underfitting: the model is too simple for the pattern.' },
    lcbias: { what: 'Learning curve of a straight line.', real: '—', see: 'Training and validation curves meet quickly, well above σ².', breaks: '—', fine: '—', detect: 'Converged curves at a high error.', fix: 'More flexibility, not more data.', line: 'High bias: more data does not help.' },
    lcvar: { what: 'Learning curve of a degree-10 polynomial.', real: '—', see: 'A wide gap that shrinks as data grow.', breaks: '—', fine: '—', detect: 'A large train–validation gap.', fix: 'More data, regularisation, simpler model.', line: 'High variance: more data helps.' },
    lcgood: { what: 'Learning curve of a degree-2 polynomial.', line: 'A good model: both curves approach the noise level.' },
    vcdeg: { what: 'Validation curve over the degree.', real: 'Choosing model complexity.', see: 'A falling training curve and a U-shaped validation curve.', breaks: '—', fine: '—', detect: '—', fix: 'validation_curve / GridSearchCV.', line: 'Pick the degree at the bottom of the validation U.' },
    vclam: { what: 'Validation curve over ridge λ.', real: 'Tuning regularisation.', see: 'Training error rises with λ; validation error is U-shaped.', breaks: '—', fine: '—', detect: '—', fix: 'RidgeCV.', line: 'Too little λ overfits, too much underfits.' },
    bvdecomp: { what: 'Bias–variance decomposition by simulation.', real: 'The theory behind every complexity choice.', see: 'Degree 1: high bias; degree 6: high variance; degree 2: lowest total.', breaks: '—', fine: '—', detect: '—', fix: '—', line: 'Expected error = bias² + variance + irreducible noise.' },
    sp8020: { what: '80/20 split.', line: '80/20 is the common default: most rows to fit, enough to test.' },
    sp7030: { what: '70/30 split.', real: 'Common with moderate data.', see: 'A slightly steadier test score; slightly less precise weights.', breaks: '—', fine: 'Both sides reasonable.', detect: '—', fix: '—', line: 'More test rows: a steadier score.' },
    sp5050: { what: '50/50 split.', real: 'When the score itself must be precise.', see: 'The steadiest test score, the least precise fit.', breaks: 'Wastes training data.', fine: 'A reliable score.', detect: '—', fix: 'Cross-validation uses all rows for both.', line: 'Half the data for testing is usually too much.' },
    sptiny: { what: 'Only 5 test rows.', real: 'Small datasets split carelessly.', see: 'The test score jumps from split to split.', breaks: 'The test score is close to useless.', fine: 'The fit itself.', detect: 'Re-split with other seeds.', fix: 'Cross-validation.', line: 'A tiny test set gives a score you cannot trust.' },
    cvnone: { what: 'No cross-validation: one split.', line: 'One split gives one noisy number.' },
    cvkfold: { what: '5-fold cross-validation.', real: 'The standard for model selection.', see: 'Five fold scores and their mean.', breaks: 'Ignores time order if the rows are a time series.', fine: 'Uses every row for validation once.', detect: '—', fix: 'cross_val_score(model, X, y, cv=KFold(5)).', line: 'k-fold averages k held-out scores.' },
    cvloo: { what: 'Leave-one-out.', real: 'Small data; least squares (free via the hat matrix).', see: 'PRESS = Σ(eᵢ/(1 − hᵢᵢ))²/n.', breaks: 'High variance; n fits for general models.', fine: 'Nearly unbiased.', detect: '—', fix: 'LeaveOneOut().', line: 'For least squares, LOO needs no refits.' },
    cvts: { what: 'Time-series split: expanding windows.', real: 'Forecasting, any data in time order.', see: 'A larger (honest) error than shuffled k-fold.', breaks: 'Early folds have little training data.', fine: 'Never uses the future to predict the past.', detect: '—', fix: 'TimeSeriesSplit(n_splits=5).', line: 'With time-ordered data, always validate forward in time.' },
    cvnested: { what: 'Nested cross-validation.', real: 'Reporting the performance of a tuned model.', see: 'The nested estimate is larger than the best inner score.', breaks: 'Costs k × k fits.', fine: 'An unbiased score for the whole tuning procedure.', detect: '—', fix: 'cross_val_score(GridSearchCV(...), X, y, cv=outer).', line: 'Tune with inner CV, report with outer CV.' },
    sdfixed: { what: 'One fixed seed.', line: 'A fixed seed makes a run reproducible, not representative.' },
    sdvaried: { what: '200 seeds for the same split ratio.', real: 'Repeated hold-out, stability checks.', see: 'A distribution of test scores and slopes.', breaks: '—', fine: 'Shows how much the split matters.', detect: '—', fix: 'Report the mean and spread, or use repeated k-fold.', line: 'Vary the seed to see the uncertainty of the score.' },
    slneq: { what: 'Solve X̃ᵀX̃w̃ = X̃ᵀy directly.', line: 'The normal equations are exact and fast for modest p, but square the condition number.' },
    slpinv: { what: 'w̃ = VΣ⁺Uᵀy from the SVD.', real: 'numpy.linalg.lstsq, sklearn LinearRegression.', see: 'The same weights; works even with collinear columns (minimum-norm solution).', breaks: 'Costs more than QR.', fine: 'The most robust solver.', detect: '—', fix: '—', line: 'The SVD gives the minimum-norm least-squares solution and handles rank deficiency.' },
    slqr: { what: 'X̃ = QR, then Rw̃ = Qᵀy.', real: 'R lm(), statsmodels OLS (pinv by default, QR as an option).', see: 'The same weights.', breaks: 'Fails on exactly collinear columns unless pivoted.', fine: 'Accuracy governed by κ(X̃), not κ(X̃)².', detect: '—', fix: '—', line: 'QR avoids forming X̃ᵀX̃.' },
    slchol: { what: 'X̃ᵀX̃ = LLᵀ, then two triangular solves.', real: 'Fast solvers when p is moderate and the problem well conditioned.', see: 'The same weights.', breaks: 'Needs X̃ᵀX̃ positive definite; squares κ.', fine: 'About twice as fast as general elimination.', detect: '—', fix: '—', line: 'Cholesky is the fast way to solve the normal equations.' },
    slgd: { what: 'Gradient descent as the solver.', real: 'Huge data or streaming data.', see: 'The same weights after enough iterations.', breaks: 'Needs a learning rate and scaled features.', fine: 'Scales to any size.', detect: '—', fix: '—', line: 'Gradient descent trades exactness for scalability.' },
    slcd: { what: 'Coordinate descent: one weight at a time, exactly.', real: 'Lasso and elastic-net solvers (glmnet, scikit-learn).', see: 'The same weights after enough sweeps; zig-zags with correlated features.', breaks: 'Slow with strongly correlated features.', fine: 'No learning rate; handles L1 penalties.', detect: '—', fix: '—', line: 'Coordinate descent is the workhorse for lasso.' },
    gdbatch: { what: 'Full-batch gradient descent.', line: 'Batch GD uses the exact gradient: smooth but expensive steps.' },
    gdsgd: { what: 'Stochastic gradient descent: one row per step.', real: 'Online learning, very large data, neural networks.', see: 'A jittery loss curve that drops fast and then hovers above the minimum.', breaks: 'Never settles exactly with a constant η.', fine: 'Cheap steps; progress after a fraction of an epoch.', detect: '—', fix: 'Decay η; average the iterates.', line: 'SGD is noisy but cheap; it needs a decaying learning rate to converge.' },
    gdmini: { what: 'Mini-batch gradient descent (8 rows per step).', real: 'The standard in deep learning.', see: 'Less jitter than SGD, more steps than batch.', breaks: 'Another hyperparameter (batch size).', fine: 'Vectorised and fast.', detect: '—', fix: '—', line: 'Mini-batch is the practical compromise.' },
    lrgood: { what: 'η = 0.5 × 2/λ_max.', line: 'A well-chosen η converges quickly and smoothly.' },
    lrtiny: { what: 'η = 0.01 × 2/λ_max.', real: 'An over-cautious setting.', see: 'The loss falls very slowly; after 100 iterations the weights are far from the minimum.', breaks: 'Wastes iterations; looks converged when it is not.', fine: 'It is stable.', detect: 'A loss curve that is still falling.', fix: 'Increase η (a learning-rate range test).', line: 'Too small an η crawls.' },
    lrnear: { what: 'η = 0.98 × 2/λ_max.', real: 'An aggressive setting.', see: 'The weights zig-zag across the valley; the loss falls unevenly.', breaks: 'Slow along the steep direction (factor |1 − ηλ_max| ≈ 0.96).', fine: 'Still converges.', detect: 'Oscillating iterates.', fix: 'Lower η a little, or add momentum.', line: 'Near the limit, gradient descent oscillates.' },
    lrbig: { what: 'η = 1.05 × 2/λ_max.', real: 'A learning rate set too high.', see: 'The loss grows every iteration and overflows.', breaks: 'Everything: the weights explode.', fine: 'Nothing.', detect: 'A rising loss curve.', fix: 'Lower η below 2/λ_max.', line: 'Above 2/λ_max, gradient descent diverges.' },
    schconst: { what: 'SGD with constant η.', line: 'Constant-η SGD hovers around the minimum.' },
    schstep: { what: 'Step decay: η halves every 5 epochs.', real: 'Classic deep-learning schedule.', see: 'The loss drops in steps as η falls.', breaks: 'Needs the drop points chosen.', fine: 'Settles near the minimum.', detect: '—', fix: '—', line: 'Step decay: big steps first, small steps later.' },
    schexp: { what: 'η = η₀·0.9^epoch.', real: 'Smooth decay.', see: 'A smooth settle.', breaks: 'Decays too fast if the rate is too small.', fine: 'Settles.', detect: '—', fix: '—', line: 'Exponential decay shrinks η by a fixed factor each epoch.' },
    schinv: { what: 'η = η₀ / (1 + epoch/2).', real: 'The classic Robbins–Monro choice for SGD.', see: 'A gradual settle.', breaks: 'Can decay too slowly.', fine: 'Theory guarantees convergence (Ση = ∞, Ση² < ∞).', detect: '—', fix: '—', line: '1/t decay is the textbook SGD schedule.' },
    opgd: { what: 'Plain gradient descent with a small η.', line: 'Plain GD crawls along a narrow valley.' },
    opmom: { what: 'Momentum (β = 0.9).', real: 'SGD with momentum: the default in vision models.', see: 'Faster progress along the valley; some overshoot.', breaks: 'Can overshoot and oscillate.', fine: 'Same η, much faster.', detect: '—', fix: '—', line: 'Momentum accumulates consistent gradient directions.' },
    opnest: { what: 'Nesterov momentum.', real: 'A common upgrade of momentum.', see: 'Like momentum with less overshoot.', breaks: '—', fine: 'Provably faster on convex problems.', detect: '—', fix: '—', line: 'Nesterov looks ahead before taking the gradient.' },
    oprms: { what: 'RMSProp.', real: 'Recurrent networks, non-stationary problems.', see: 'Similar step sizes in every direction; jitters near the minimum.', breaks: 'Does not settle with a constant η.', fine: 'Insensitive to feature scale.', detect: '—', fix: 'Decay η.', line: 'RMSProp normalises each weight’s step by its gradient history.' },
    opadam: { what: 'Adam.', real: 'The default optimiser for neural networks.', see: 'Fast, steady progress; steps about η in size.', breaks: 'Can generalise worse than SGD in deep learning; needs η decay to settle.', fine: 'Works out of the box on most problems.', detect: '—', fix: '—', line: 'Adam = momentum + RMSProp + bias correction.' },
    inzero: { what: 'Start at w̃ = 0.', line: 'For a convex loss, zero is as good a start as any.' },
    inrand: { what: 'Start from small random weights.', real: 'Neural networks (to break symmetry).', see: 'The same answer as from zeros.', breaks: '—', fine: 'Convex loss: same minimum.', detect: '—', fix: '—', line: 'Random starts matter for neural networks, not for least squares.' },
    infar: { what: 'Start far away, at [40, −40, 40].', real: 'A bad warm start.', see: 'More iterations, the same minimum.', breaks: 'Only time.', fine: 'The answer.', detect: '—', fix: '—', line: 'A convex bowl forgives any start.' },
    stfixed: { what: 'Stop after 100 iterations.', line: 'A fixed budget may stop before convergence.' },
    stgrad: { what: 'Stop when ‖∇L‖ < 0.01.', real: 'The usual tolerance in solvers.', see: 'Stops close to the minimum.', breaks: 'The tolerance depends on the scale of the loss.', fine: 'Adapts to the problem.', detect: '—', fix: '—', line: 'A small gradient means you are near the bottom.' },
    stloss: { what: 'Stop when the loss changes by less than 10⁻⁶.', real: 'scikit-learn tol on the loss.', see: 'Stops near the minimum.', breaks: 'A slow, flat valley can trigger it early.', fine: 'Cheap to check.', detect: '—', fix: '—', line: 'Loss tolerance stops when progress stalls.' },
    stearly: { what: 'Early stopping on a validation split.', real: 'Neural networks, gradient boosting.', see: 'It stops when the validation loss stops improving and keeps the best weights.', breaks: 'Uses fewer rows for fitting.', fine: 'Acts like a penalty on the weights.', detect: '—', fix: '—', line: 'Early stopping is regularisation by iteration count.' },
    sgscaled: { what: 'Gradient descent on standardised features.', line: 'Standardised features make the bowl round, so GD converges fast.' },
    sgunscaled: { what: 'Gradient descent on the raw features (x₂ in thousands).', real: 'Forgetting StandardScaler before SGDRegressor.', see: 'After 200 iterations the weights are far from least squares; the loss is still high.', breaks: 'Convergence: κ is in the millions.', fine: 'The closed form is unaffected.', detect: 'A slowly falling loss; huge κ.', fix: 'StandardScaler before any gradient method.', line: 'Unscaled features cripple gradient descent but not the normal equations.' },
    ofpcr: { what: 'Regress y on the first k principal components of the features (k by CV).', real: 'Spectroscopy, many related sensors, survey scales.', see: 'Fewer columns, uncorrelated; weights on the original features close to ridge.', breaks: 'The components ignore y, so a low-variance direction that predicts y can be dropped.', fine: 'Removes collinearity completely.', detect: '—', fix: 'Pipeline(StandardScaler, PCA(k), LinearRegression), k by CV.', line: 'PCR keeps the high-variance directions of X, whether or not they predict y.' },
    ofpls: { what: 'Partial least squares: components chosen to covary with y (k by CV).', real: 'Chemometrics; many more features than rows.', see: 'Usually fewer components than PCR for the same error.', breaks: 'Harder to interpret; components depend on y, so they can overfit.', fine: 'Works with p > N.', detect: '—', fix: 'PLSRegression(n_components=k).', line: 'PLS builds each component to predict y, not just to summarise X.' },
    ofbayes: { what: 'A normal prior N(0, 1) on every standardised weight; the posterior mean and SD.', real: 'Small data with prior knowledge; when a full uncertainty is wanted.', see: 'Weights slightly shrunk (like ridge with λ = σ²/τ²) and a credible interval for each.', breaks: 'A wrong, strong prior biases the answer.', fine: 'With much data it agrees with OLS.', detect: '—', fix: 'BayesianRidge (prior estimated from the data), or PyMC for full models.', line: 'Ridge is the Bayesian posterior mean under a normal prior.' },

    /* ---------- data properties ---------- */
    outnone: { what: 'Every row follows the same pattern.', line: 'No row stands apart: the largest Cook’s distance is small.' },
    outy: { what: 'One row has a far-too-large y at an ordinary x.', real: 'A typo with an extra digit, a one-off event, a unit mix-up.', see: 'A large studentised residual; a modest Cook’s distance, because the leverage is ordinary.', breaks: 'It inflates s² and every SE, and shifts the intercept.', fine: 'The slope moves little.', detect: 'z-scores of y, studentised residuals, Cook’s distance.', fix: 'Check the row; if it is an error, correct or remove it; otherwise use a robust loss (Huber) and report both fits.', line: 'An outlier in y at a typical x mostly costs precision, not the slope.' },
    levon: { what: 'One row is far out in x but on the trend.', real: 'One very large but correctly priced house.', see: 'Huge leverage, small residual, modest Cook’s distance.', breaks: 'Nothing: it is good leverage.', fine: 'The slope, and its SE actually shrinks.', detect: 'Leverage h far above p/N.', fix: 'Keep it, but check that the relationship really holds that far out.', line: 'High leverage is not bad by itself; leverage plus a large residual is.' },
    levoff: { what: 'One row is far out in x and far off the trend.', real: 'A data-entry error in both columns, or a different kind of unit.', see: 'Huge leverage and a large residual: Cook’s distance far above 1.', breaks: 'The slope is pulled toward that one row.', fine: 'Nothing else is wrong with the data.', detect: 'Cook’s distance, DFBETAS, and a refit without the row.', fix: 'Investigate the row; report the fit with and without it; use a robust method.', line: 'One high-leverage, off-trend row can decide the slope on its own.' },
    outcluster: { what: 'A small group of rows is off the trend together.', real: 'A batch measured with a faulty instrument, or a sub-population.', see: 'The rows sit together; one-at-a-time Cook’s distances can stay modest.', breaks: 'The line is pulled toward the group.', fine: 'The other rows are fine.', detect: 'Look at the residual plot; refit without the whole group; robust methods.', fix: 'Find out what the rows have in common; model them as a group, or use a robust method.', line: 'Outliers that cluster can mask each other.' },
    nlarge: { what: 'Plenty of rows for the number of coefficients.', line: 'N is much larger than p: SEs are small and train and test error agree.' },
    nmod: { what: 'A moderate number of rows.', real: 'Most business datasets.', see: 'SEs about twice as large as with 200 rows.', breaks: 'Only precision.', fine: 'Everything.', detect: 'The SEs and the width of the intervals.', fix: 'More data if precision matters.', line: 'SE shrinks like 1/√N.' },
    nsmall: { what: 'Few rows for the number of coefficients.', real: 'Pilot studies, rare events, expensive experiments.', see: 'Wide intervals, a t critical value well above 2, test error above training error.', breaks: 'Precision, and the power of every diagnostic.', fine: 'The estimate is still unbiased.', detect: 'Count the spare rows N − p.', fix: 'Fewer features, regularisation (ridge), or more data.', line: 'With few spare rows, the model memorises noise and the tests cannot see problems.' },
    nap: { what: 'Only one more training row than coefficients.', real: 'Wide data: many features measured on few subjects.', see: 'Training error near 0, test error large, intervals enormous (t critical value 12.7 with 1 df).', breaks: 'Every estimate of uncertainty, and generalisation.', fine: 'The arithmetic still works.', detect: 'N − p is tiny.', fix: 'Drop features, use ridge or lasso, or collect more rows.', line: 'N close to p means the model can fit almost anything, including noise.' },
    nlp: { what: 'Fewer training rows than coefficients.', real: 'Genomics (thousands of genes, dozens of patients), text with many words.', see: 'Training error exactly 0; X̃ᵀX̃ has zero eigenvalues; s², SEs and tests undefined.', breaks: 'Uniqueness of the solution and all inference.', fine: 'The minimum-norm solution still exists.', detect: 'rank(X) < p.', fix: 'Regularisation (ridge, lasso), dimension reduction (PCA), or fewer features.', line: 'With N < p there are infinitely many perfect fits: least squares alone cannot choose.' },
    nslow: { what: 'Noise as set on the slider.', line: 'The noise level sets s, the SEs and the test RMSE floor.' },
    nszero: { what: 'No noise at all: every point is on the line.', real: 'Only deterministic simulations or exact formulas.', see: 'R² = 1, every residual 0, SEs 0, t infinite.', breaks: 'All the statistics: there is nothing random left to test.', fine: 'The coefficients are exact.', detect: 'SSE = 0.', fix: 'Suspect a formula or leakage: real data always have noise.', line: 'Perfect fit means no uncertainty can be measured, and usually means something is wrong with the data.' },
    nsmod: { what: 'Noticeably more noise.', real: 'Survey data, human behaviour.', see: 'Lower R², larger SEs, larger test RMSE.', breaks: 'Precision and R².', fine: 'The slope is still unbiased.', detect: 's and R².', fix: 'More rows, better measurement, or more informative features.', line: 'Noise lowers R² but does not bias the slope.' },
    nshigh: { what: 'Very large noise.', real: 'Financial returns, single-subject measurements.', see: 'R² close to 0 even though the slope is real.', breaks: 'Precision: the slope may not even be significant.', fine: 'On average the slope is still right.', detect: 's is large compared with the spread of the fitted line.', fix: 'Many more rows, or better features.', line: 'A low R² can still come with a real, useful slope.' },
    nspure: { what: 'y has nothing to do with x.', real: 'Testing an idea that is wrong.', see: 'R² near 0, F-test not significant, test R² near or below 0.', breaks: 'Nothing technical; there is simply no signal.', fine: 'The tests correctly say "no effect" about 95% of the time.', detect: 'The F-test and test R².', fix: 'Accept it, or look for other features.', line: 'With pure noise, 5% of samples still show a "significant" slope.' },
    rwide: { what: 'x covers the whole range of interest.', line: 'The data cover the range where the model is used.' },
    rrestrict: { what: 'Only a narrow range of x was observed.', real: 'A study that recruited one age group; prices that only varied a little.', see: 'A large SE for the slope; a cloud that looks flat.', breaks: 'Precision of the slope, and anything outside the range.', fine: 'Predictions inside the range.', detect: 'The SD and range of x; SE = s / √Σ(x − x̄)².', fix: 'Collect data over a wider range if you can design the study.', line: 'Precision of a slope comes from the spread of x.' },
    rgap: { what: 'No rows in the middle of the x range.', real: 'Sensor downtime, a price that jumped.', see: 'A gap in the scatter; the line passes straight through.', breaks: 'Any shape inside the gap is invisible.', fine: 'The line where there are rows.', detect: 'Histogram of x.', fix: 'Collect data in the gap before trusting predictions there.', line: 'Interpolating across a gap is still a guess.' },
    rextrap: { what: 'The model is used beyond the training range.', real: 'Forecasting a boom with data from normal years.', see: 'Test error much larger than training error; test residuals trend with x.', breaks: 'Predictions outside the data.', fine: 'Predictions inside the data.', detect: 'Compare the x range of new data with the training range.', fix: 'Do not extrapolate; or collect data in the new region; or use domain knowledge about the shape.', line: 'A line is only validated where there was data.' },
    irnone: { what: 'Every column is useful.', line: 'No useless columns: adjusted R² and R² agree.' },
    irfew: { what: 'A few useless columns.', real: 'Fields added "just in case".', see: 'R² rises a little, adjusted R² does not; their coefficients are near 0.', breaks: 'A little test accuracy.', fine: 'The real coefficients.', detect: 'p-values, adjusted R², cross-validation.', fix: 'Feature selection or regularisation.', line: 'R² never falls when you add a column, so use adjusted R² or a test set.' },
    irmany: { what: 'Many useless columns, close to the number of rows.', real: 'Wide datasets with many weak candidate features.', see: 'Training error falls, test error rises, and some noise columns look significant.', breaks: 'Generalisation and inference (multiple testing).', fine: 'Nothing that matters.', detect: 'A gap between train and test error; adjusted R².', fix: 'Lasso, cross-validated selection, or domain knowledge.', line: 'With many noise columns some will look significant by luck: that is multiple testing.' },
    ircopy: { what: 'The same information appears twice.', real: 'Height in cm and in inches; two versions of one score.', see: 'Two nearly identical columns, a high VIF.', breaks: 'The individual coefficients and their SEs.', fine: 'Predictions.', detect: 'Correlation between features, VIF.', fix: 'Keep one of them.', line: 'Duplicate information splits the credit arbitrarily.' },
    mnone: { what: 'Every value recorded.', line: 'No missing values.' },
    mcar: { what: 'Values are missing by pure chance (MCAR).', real: 'Lost forms, random sensor failures.', see: 'The missing share is the same everywhere.', breaks: 'Only the number of rows: larger SEs.', fine: 'The estimate is unbiased.', detect: 'Compare rows with and without missing values: they look alike.', fix: 'Dropping the rows is fine; multiple imputation recovers some precision.', line: 'MCAR costs precision, not bias.' },
    mar: { what: 'The chance of missing depends on an observed column (MAR).', real: 'Older customers skip an online question.', see: 'The missing share changes with x.', breaks: 'The mean of y computed from the kept rows.', fine: 'The regression slope, because x is in the model.', detect: 'Model the missingness on the observed columns.', fix: 'Keep the cause in the model, or multiple imputation using it.', line: 'MAR is fine for regression if the cause of missingness is one of the features.' },
    mnar: { what: 'The chance of missing depends on the missing value itself (MNAR).', real: 'High earners leaving income blank; sick patients dropping out.', see: 'Little in the kept data: the high-y rows are simply not there.', breaks: 'The slope is biased.', fine: 'Nothing can be fully fixed from the data alone.', detect: 'Knowledge of the collection process, follow-up surveys, sensitivity analysis.', fix: 'Selection models (Heckman), sensitivity analysis, collecting the missing values.', line: 'MNAR biases the estimates, and the data alone cannot show it.' },
    tcont: { what: 'A continuous, unbounded y.', line: 'y is the right type for least squares.' },
    tskew: { what: 'y grows multiplicatively with a long right tail.', real: 'Prices, incomes, file sizes, waiting times.', see: 'A curved, fanning residual plot; skewed residuals.', breaks: 'Linearity, constant variance and normality all at once.', fine: 'Rough predictions in the middle.', detect: 'Histogram of y, residual plot, Box-Cox.', fix: 'Model log(y), or a GLM with a log link.', line: 'For multiplicative data, log(y) turns a curve into a line and a funnel into a band.' },
    tbound: { what: 'y can only lie between 0 and 20.', real: 'Percentages, exam scores, ratings.', see: 'Residuals curve at both ends; predictions beyond the bounds.', breaks: 'Predictions near the bounds.', fine: 'The middle of the range.', detect: 'Compare predictions with the possible range.', fix: 'A logistic-type model, or a transform such as log(y / (20 − y)).', line: 'A straight line does not know that y has limits.' },
    tcount: { what: 'y is a count of events.', real: 'Visits per day, claims per policy, defects per batch.', see: 'Whole numbers; the spread grows with the mean.', breaks: 'Constant variance; predictions can be negative.', fine: 'A rough trend.', detect: 'All y are whole numbers; variance rises with the mean.', fix: 'Poisson or negative binomial regression.', line: 'Counts call for Poisson regression: log(mean) is linear, and the variance follows the mean.' },
    cnone: { what: 'Only numeric features.', line: 'No categorical features.' },
    cbin: { what: 'A two-level category, as one 0/1 column.', real: 'Treated vs control, weekday vs weekend.', see: 'Two parallel lines.', breaks: 'Nothing, if encoded correctly.', fine: 'Everything.', detect: '—', fix: 'One 0/1 column; its coefficient is the gap between the levels.', line: 'A dummy coefficient is the difference from the reference level.' },
    cmulti: { what: 'A category with four levels, one-hot encoded with one level dropped.', real: 'Region, product type, weekday.', see: 'One line per level, parallel.', breaks: 'Nothing, if one level is dropped.', fine: 'Everything.', detect: '—', fix: 'k − 1 dummy columns; test the whole category with a partial F-test.', line: 'k levels need k − 1 dummies when there is an intercept.' },
    chigh: { what: 'A category with many levels, most of them rare.', real: 'Zip code, user ID, product SKU.', see: 'Dozens of dummy columns; rare levels with huge SEs.', breaks: 'Generalisation: rare levels are memorised, unseen levels cannot be predicted.', fine: 'Common levels.', detect: 'Rows per level.', fix: 'Group rare levels, target encoding with cross-fitting, or a mixed model (random effects).', line: 'High-cardinality one-hot encoding overfits: shrink the rare levels.' },
    sgnone: { what: 'One population.', line: 'No hidden groups.' },
    sgint: { what: 'Two groups with different baselines, not in the model.', real: 'Two stores, two machines, men and women.', see: 'Two bands of residuals.', breaks: 'The slope, if the groups also differ in x.', fine: 'Nothing else.', detect: 'Colour the residuals by any candidate grouping.', fix: 'Add the group as a dummy column.', line: 'An omitted group is an omitted variable.' },
    sgslope: { what: 'Two groups where x has a different effect.', real: 'A drug that works for one age group only.', see: 'Residuals fan out along x.', breaks: 'One slope is wrong for both groups.', fine: 'Nothing.', detect: 'Residuals by group, interaction tests.', fix: 'Add the group and the group × x interaction.', line: 'Different slopes by group need an interaction term.' },
    simpson: { what: 'The pooled relationship has the opposite sign to the one inside each group.', real: 'Admission rates by department; treatment effects by severity.', see: 'Within each colour the trend goes up, overall it goes down.', breaks: 'The sign of the slope.', fine: 'Nothing.', detect: 'Stratify by the candidate group.', fix: 'Include the group; think causally about which comparison you want.', line: 'Simpson’s paradox: aggregating groups can reverse a relationship.' },
    shnone: { what: 'Test data like training data.', line: 'No shift: the test score estimates real performance.' },
    shfeat: { what: 'The inputs move, the rule stays (covariate shift).', real: 'A model built on one region used in another.', see: 'The x histogram of the new data differs.', breaks: 'Only a model that is wrong in the new region.', fine: 'A correctly specified model.', detect: 'Compare the input distributions (train vs new).', fix: 'Reweight training rows toward the new population, or make sure the model is right there.', line: 'Covariate shift hurts only where the model is wrong.' },
    shrel: { what: 'The rule linking x to y changes (concept drift).', real: 'Customer behaviour after a policy change; markets after a crisis.', see: 'Test residuals trend with x; test error jumps.', breaks: 'Every prediction after the change.', fine: 'Nothing that depends on the old rule.', detect: 'Monitor errors over time; time-ordered validation.', fix: 'Retrain on recent data, weight recent rows more, or model the change.', line: 'Concept drift needs monitoring and retraining, not more old data.' },
    lknone: { what: 'No leakage.', line: 'Every feature is known before y, and the split comes first.' },
    lktarget: { what: 'A feature is built from y or recorded after it.', real: '"Total paid" predicting "default"; a diagnosis code predicting the disease.', see: 'One feature predicts y almost perfectly; test score too good to be true.', breaks: 'Real-world performance.', fine: 'Nothing.', detect: 'Ask when each column is known; suspiciously high importance.', fix: 'Remove every column not available at prediction time.', line: 'If a feature looks too good to be true, check whether it is known before the outcome.' },
    lkprep: { what: 'A step that learns from y (target encoding) used every row before the split.', real: 'Target encoding, feature selection or imputation fitted on the full dataset.', see: 'Test score better than the honest pipeline gives, and a useless category that looks important.', breaks: 'The test score as an estimate of real performance.', fine: 'Scaling for plain OLS changes nothing.', detect: 'Check that every fitted step is inside the training fold.', fix: 'Split first; put every learning step in a pipeline fitted on the training rows only.', line: 'Anything that learns from data must learn from the training rows only.' },
    linear: { what: 'The true relationship is a straight line, so the model is the right shape.', line: 'The line fits: residuals are random around zero all along x, and RESET does not reject.' },
    quadratic: { what: 'The truth curves upward (convex), but we fit a straight line.', real: 'Fuel use vs speed, cost vs volume beyond capacity, medical risk vs dose.', see: 'Residuals form a U: positive at both ends, negative in the middle.', breaks: 'Predictions are systematically off by region, worst at the edges and when extrapolating. The slope is an average of a changing effect.', fine: 'The solver still finds the best straight line exactly.', detect: 'Scatter plot in EDA, residual-vs-x or residual-vs-fitted plot, Ramsey RESET.', fix: 'Add x², use a log or other transform, or use splines.', line: 'If the residual plot shows a U-shape, the linearity assumption fails; I would add a squared term or transform x, refit and re-check RESET.' },
    log: { what: 'y rises quickly and then levels off, but we fit a straight line.', real: 'Returns to advertising spend, learning curves, diminishing returns in general.', see: 'Residuals form an upside-down U: the line is too high at both ends and too low in the middle.', breaks: 'Predictions are biased by region, and extrapolating to large x overshoots badly.', fine: 'The fitting machinery itself.', detect: 'Scatter plot, residual plot, RESET.', fix: 'Use log(x) as the feature, or a spline.', line: 'The effect of x shrinks as x grows, so I would model log(x) instead of x.' },
    sshape: { what: 'y is flat, then rises steeply, then flattens again.', real: 'Adoption of a technology over time, dose–response curves.', see: 'Residuals follow a wave across x.', breaks: 'One slope cannot describe three different regimes.', fine: 'The fitting machinery.', detect: 'Scatter and residual plots, RESET.', fix: 'Splines, a logistic-shaped feature, or a non-linear model.', line: 'An S-shaped relationship needs splines or a non-linear model; a single slope averages three regimes.' },
    step: { what: 'The mean of y jumps at a threshold.', real: 'Eligibility cut-offs, tax brackets, policy changes on a date.', see: 'Residuals are one sign below the threshold and the other above it.', breaks: 'The line smears the jump into a slope that is not really there.', fine: 'The fitting machinery.', detect: 'Scatter plot, residuals vs x, RESET.', fix: 'Add a 0/1 indicator for "above the threshold", or a piecewise model.', line: 'A jump needs an indicator variable; a straight line turns it into a fake gradual slope.' },
    periodic: { what: 'A straight trend plus a repeating wave.', real: 'Seasonality in sales, daily temperature cycles.', see: 'Residuals oscillate in a regular wave.', breaks: 'The wave is left in the errors, so the errors are also autocorrelated.', fine: 'The overall trend can still be estimated.', detect: 'Residuals in order, RESET, Durbin–Watson.', fix: 'Add sine and cosine terms or seasonal dummies.', line: 'Seasonality left in the residuals shows up as a wave; I would add seasonal terms.' },
    interaction: { what: 'Two groups have different slopes, but the model gives them one shared slope.', real: 'The effect of training hours on output differs between junior and senior staff.', see: 'Each group\'s residuals tilt in opposite directions: a cross shape.', breaks: 'The single slope is wrong for both groups.', fine: 'The intercept shift between groups is captured.', detect: 'Plot the residuals by group; RESET can also fire.', fix: 'Add the interaction term x × group.', line: 'If the effect of x depends on the group, I add an x-times-group interaction; otherwise the one slope is wrong for everyone.' },
    indep: { what: 'Each row\'s error is drawn fresh.', line: 'Independent errors: Durbin–Watson near 2, no streaks in the residuals.' },
    posar: { what: 'Each error carries over part of the previous one (positive autocorrelation).', real: 'Time series: monthly sales, stock prices, temperatures, anything where today resembles yesterday.', see: 'Long streaks of residuals on the same side of the line; the lag plot tilts upward; Durbin–Watson well below 2.', breaks: 'The classical standard errors are too small, so p-values are too small and intervals too narrow. A random train/test split leaks neighbouring rows.', fine: 'The coefficients stay unbiased.', detect: 'Residuals in time order, a lag plot, Durbin–Watson, Breusch–Godfrey.', fix: 'Newey–West (HAC) standard errors, adding lags or trends, GLS (Cochrane–Orcutt), and a time-ordered split.', line: 'With autocorrelated errors the slope is still unbiased but the classical SEs are overconfident; I would use Newey–West SEs and split by time.' },
    negar: { what: 'Errors tend to flip sign from one row to the next (negative autocorrelation).', real: 'Over-correcting processes: inventory that is over-ordered then under-ordered.', see: 'Residuals zig-zag; Durbin–Watson above 2.', breaks: 'The classical SEs are wrong (here usually too large, so the model is too cautious).', fine: 'The coefficients stay unbiased.', detect: 'Residuals in order, Durbin–Watson.', fix: 'Newey–West standard errors, or model the dynamics.', line: 'Zig-zag residuals mean negative autocorrelation; the estimates are fine, the SEs need a HAC correction.' },
    cluster: { what: 'Rows come in groups that share a common shock.', real: 'Students in the same class, patients in the same hospital, repeated measurements of the same customer.', see: 'Whole clusters sit above or below the line; a large share of the residual variance is between clusters.', breaks: 'The classical SEs are far too small, because the effective sample size is closer to the number of clusters than to the number of rows.', fine: 'The coefficients stay unbiased.', detect: 'Plot residuals by group and compute the intraclass correlation.', fix: 'Cluster-robust SEs, a mixed (random-effects) model, and a group-wise train/test split.', line: 'Clustered data need clustered standard errors and a split by group; otherwise I am counting one shock many times.' },
    dupes: { what: 'The same observations appear several times.', real: 'A bad join, repeated form submissions, data appended twice.', see: 'Identical rows; residuals come in identical blocks.', breaks: 'N looks bigger than the real information, so SEs shrink by about √(copies), and copies land in both train and test.', fine: 'The coefficients are unchanged.', detect: 'A duplicate check in cleaning.', fix: 'Remove duplicates before anything else.', line: 'Duplicates do not move the line but they fake extra evidence; I remove them in cleaning.' },
    constant: { what: 'The errors have the same spread everywhere.', line: 'Constant variance: an even band of residuals, Breusch–Pagan does not reject.' },
    increasing: { what: 'The error spread grows with x.', real: 'Spending vs income, house price vs size: bigger values vary more.', see: 'A funnel opening to the right in the residual plot.', breaks: 'The classical SEs, p-values and intervals; OLS is no longer the most efficient estimator.', fine: 'The coefficients stay unbiased.', detect: 'Residual-vs-fitted plot, Breusch–Pagan, White test.', fix: 'HC (robust) standard errors, weighted least squares, or a log transform of y.', line: 'A funnel means heteroscedasticity; the slope is still unbiased, but I would report HC-robust SEs or model log y.' },
    decreasing: { what: 'The error spread shrinks as x grows.', real: 'Measurements that get relatively more precise for larger quantities.', see: 'A funnel narrowing to the right.', breaks: 'The classical SEs.', fine: 'The coefficients stay unbiased.', detect: 'Residual plot, Breusch–Pagan.', fix: 'Robust SEs or WLS.', line: 'A narrowing spread is still heteroscedasticity: robust SEs.' },
    bowtie: { what: 'Small spread in the middle of x, large at both ends.', real: 'A process tightly controlled around its set point.', see: 'A bow-tie shape in the residual plot.', breaks: 'The classical SEs. Breusch–Pagan may miss it because the variance is not linear in x.', fine: 'The coefficients stay unbiased.', detect: 'The residual plot; the White test (it includes x²).', fix: 'Robust SEs or WLS.', line: 'Variance that depends on x² can slip past Breusch–Pagan; the White test or the plot catches it.' },
    groupvar: { what: 'One group has small errors, the other large ones.', real: 'Two machines or two labs, one precise and one sloppy.', see: 'Residuals by group: one tight, one wide.', breaks: 'The classical SEs. Breusch–Pagan on x misses it, because the variance depends on the group, not on x.', fine: 'The coefficients stay unbiased.', detect: 'Plot residuals by group and test variance by group.', fix: 'Robust SEs, or WLS with per-group weights.', line: 'Always look at residuals by group; a variance test on x alone can miss group differences.' },
    normal: { what: 'The errors follow a bell curve.', line: 'Normal errors: Q–Q plot on the diagonal, Jarque–Bera does not reject.' },
    rskew: { what: 'Most errors are slightly negative, with a few large positive ones.', real: 'Waiting times, delivery delays, incomes.', see: 'A histogram with a right tail; the Q–Q plot bends up at the right.', breaks: 'Exact small-sample intervals; prediction intervals in the tail.', fine: 'Unbiased, BLUE coefficients; with moderate N the tests are approximately right.', detect: 'Histogram of residuals, Q–Q plot, Jarque–Bera, Shapiro–Wilk.', fix: 'Often a log transform of y; or bootstrap intervals.', line: 'Skewed errors do not bias OLS; with enough data the CLT covers the tests, and a log of y often fixes it.' },
    lskew: { what: 'A few large negative errors.', real: 'Scores near a ceiling.', see: 'A left tail in the histogram.', breaks: 'Exact small-sample intervals.', fine: 'The coefficients.', detect: 'Q–Q plot, Jarque–Bera.', fix: 'Transform y, or bootstrap.', line: 'Normality matters least: it only affects exact small-sample inference.' },
    heavy: { what: 'Occasional extreme errors (heavy tails).', real: 'Financial returns, sensor glitches.', see: 'Points far out on both ends of the Q–Q plot; kurtosis well above 3.', breaks: 'Extreme rows pull the line (OLS squares big errors); intervals in the tails.', fine: 'The coefficients are still unbiased.', detect: 'Q–Q plot, kurtosis, Jarque–Bera, Cook\'s distance.', fix: 'Robust regression (Huber), check the outliers, bootstrap.', line: 'Heavy tails make OLS sensitive to a few rows; I would check them and consider Huber loss.' },
    light: { what: 'Errors never stray far from 0 (light tails).', real: 'Rounding errors, bounded noise.', see: 'A flat-topped histogram; the Q–Q ends flatten.', breaks: 'Very little.', fine: 'Almost everything.', detect: 'Q–Q plot; Jarque–Bera often misses it.', fix: 'Usually nothing.', line: 'Light tails are a harmless departure; tests often do not even detect it.' },
    bimodal: { what: 'Errors cluster around +σ and −σ.', real: 'Two hidden subpopulations mixed together.', see: 'Two humps in the histogram; a step in the Q–Q plot.', breaks: 'Exact small-sample inference, and it hints at a missing grouping variable.', fine: 'The coefficients.', detect: 'Histogram of residuals.', fix: 'Find and add the missing group variable.', line: 'Two humps in the residuals usually mean a missing categorical feature.' },
    uncorr: { what: 'The features are unrelated to each other.', line: 'No multicollinearity: VIFs near 1.' },
    moderate: { what: 'Two features are moderately correlated (r ≈ 0.6).', real: 'Age and income.', see: 'A tilted cloud in the x₁-vs-x₂ scatter; VIF around 1.5.', breaks: 'Slightly larger SEs.', fine: 'Nearly everything.', detect: 'The correlation matrix and VIF.', fix: 'Usually nothing.', line: 'Some correlation between features is normal; it only becomes a problem above about VIF 5–10.' },
    high: { what: 'Two features are almost the same (r ≈ 0.97).', real: 'House size and number of rooms, height in cm and shoe size.', see: 'A thin cigar in the x₁-vs-x₂ scatter; VIF above 10; large condition number.', breaks: 'Individual coefficients swing wildly between samples and can flip sign; their SEs inflate by √VIF.', fine: 'Predictions inside the data range, the overall F test and R².', detect: 'VIF, condition number, unstable coefficients.', fix: 'Drop or combine features, PCA, ridge regression.', line: 'High multicollinearity inflates the SEs of the individual coefficients but leaves predictions fine; ridge or dropping one feature helps.' },
    perfect: { what: 'One feature is an exact multiple of another.', real: 'The same quantity recorded in two units.', see: 'Points on an exact line in the x₁-vs-x₂ scatter; VIF infinite; det(XᵀX) = 0.', breaks: 'There is no unique solution: infinitely many weight pairs give identical predictions.', fine: 'Predictions.', detect: 'Rank of X below p, singular XᵀX.', fix: 'Drop the duplicate feature.', line: 'With perfect collinearity XᵀX is singular, so the coefficients are not identifiable; drop one column.' },
    combo: { what: 'One feature is an exact sum of others.', real: 'Total spend kept next to its parts.', see: 'No single pair looks perfectly correlated, but the rank of X is below p and VIF is infinite.', breaks: 'There is no unique solution.', fine: 'Predictions.', detect: 'Rank or VIF; pairwise correlations miss it.', fix: 'Drop the total or one of its parts.', line: 'Pairwise correlations can miss a combination of three features; VIF or the rank catches it.' },
    dummytrap: { what: 'All dummies of a category are kept alongside the intercept.', real: 'One-hot encoding without dropping a level.', see: 'A + B + C = 1 on every row, the same as the intercept column.', breaks: 'XᵀX is singular; the category coefficients have no unique meaning.', fine: 'Predictions, and the slope of x.', detect: 'Rank of X, VIF.', fix: 'Drop one dummy: it becomes the reference level.', line: 'With an intercept, keep k − 1 dummies for k categories; the dropped one is the baseline the others are compared with.' },
    exo: { what: 'The errors are unrelated to x.', line: 'Exogeneity holds: the slope estimates the causal effect.' },
    confounder: { what: 'A hidden variable drives both x and y.', real: 'Ice-cream sales and drownings (both driven by hot weather); education and income (both driven by family background).', see: 'Nothing in the residuals. The residuals are always uncorrelated with x, so the plots look perfect.', breaks: 'The slope is biased (omitted-variable bias), and more data does not fix it. Confidence intervals are centred on the wrong value.', fine: 'Predictive accuracy on similar data can still be good.', detect: 'Domain knowledge about what else drives x and y; comparing results with and without plausible controls.', fix: 'Include the confounder, use instrumental variables, or run an experiment.', line: 'Omitted-variable bias cannot be seen in the residuals; correlation is not causation, so I would add the confounder or find an instrument.' },
    measerr: { what: 'x is measured with random error.', real: 'Self-reported income, noisy sensors.', see: 'Nothing obvious; the slope is just flatter than it should be.', breaks: 'The slope is shrunk toward 0 (attenuation bias).', fine: 'Predictions from noisy x, if the future x is just as noisy.', detect: 'Repeated measurements or knowledge of the measurement process.', fix: 'Better measurement, errors-in-variables models, instruments.', line: 'Noise in x biases the slope toward zero; noise in y only adds variance.' },
    reverse: { what: 'y also influences x.', real: 'Police numbers and crime, price and demand.', see: 'Nothing in the residuals.', breaks: 'The slope mixes the effect of x on y with the effect of y on x.', fine: 'Prediction of y from x, if the system does not change.', detect: 'Thinking about the timing and the mechanism.', fix: 'Instrumental variables, a structural model, or lagged x.', line: 'With feedback from y to x, OLS cannot separate cause from effect; an instrument or a natural experiment is needed.' }
  };

  function elevator(c){
    const { P, a, v, isBase } = c, j = c.d.focus[0], nm = c.d.names[j], k = V[v.id] || {};
    let s = `Linear regression predicts a number as a weighted sum of the inputs plus a starting value. It picks the weights that make the average squared error as small as possible, which can be solved exactly (the normal equations) or approached step by step (gradient descent). I split the data first, so I can test on rows the model never saw. After fitting, I check that the leftover errors look like random noise, because the uncertainty numbers (standard errors, p-values, intervals) rely on that. Here the slope for ${nm} is ${n(P.wOrig[j], 3)}${isFinite(P.seOrig[j]) ? ` ± ${n(P.seOrig[j], 3)}` : ''}, and the test error is ${n(P.rmseTe)}.`;
    if (!isBase) s += ` In this run ${a.branch === 'assumptions' ? `<b>${esc(a.name.toLowerCase())}</b> is violated` : a.branch === 'data' ? `the data property <b>${esc(a.name.toLowerCase())}</b> matters` : `the choice <b>${esc(a.name.toLowerCase())}: ${esc(v.name)}</b> is made`}: ${esc((k.what || '').replace(/\.$/, '').toLowerCase())}. ${esc(k.breaks || '')} ${k.fine ? `What still works: ${esc(k.fine.charAt(0).toLowerCase() + k.fine.slice(1))}` : ''} ${k.fix ? `The fix: ${esc(k.fix)}` : ''}`;
    return s;
  }

  function card(c){
    const { a, v, isBase } = c, k = V[v.id] || {}, A = ASSUME[a.id];
    const AL = a.branch === 'assumptions' ? 'The assumption' : a.branch === 'data' ? 'The healthy case' : 'The idea', rows = isBase ? [[AL, A.rule], ['Why it matters', A.why], ['Here', k.line]] :
      [[AL, A.rule], ['What is different here', k.what], ['Where it happens in real data', k.real], ['What you would see', k.see], ['What it breaks', k.breaks], ['What still works', k.fine], ['How to detect it', k.detect], ['How to fix it', k.fix], ['One line for the interview', k.line]];
    return `<dl class="nt-card">${rows.filter(r => r[1]).map(([t, d]) => `<div><dt>${t}</dt><dd>${esc(d)}</dd></div>`).join('')}</dl>`;
  }

  const FOLLOW = [
    ['What are the assumptions of linear regression?', 'Linearity in the parameters; independent errors; constant error variance; errors with mean zero that are unrelated to x (exogeneity); no perfect multicollinearity; and, for exact small-sample tests, normal errors. A common short form is LINE: Linear, Independent, Normal, Equal variance.'],
    ['Which assumption violations bias the coefficients, and which only the standard errors?', 'Bias: non-linearity (wrong model) and endogeneity (confounders, measurement error in x, reverse causality). Only the SEs: autocorrelation, clustering, heteroscedasticity, duplicates. Neither, mostly: non-normal errors with moderate N. Instability rather than bias: multicollinearity.'],
    ['What does Gauss–Markov say?', 'If the errors have mean zero, constant variance, and are uncorrelated, and X has full rank, then OLS has the smallest variance among all linear unbiased estimators (BLUE). Normality is not needed.'],
    ['Closed form or gradient descent?', 'The closed form is exact and fast for a modest number of features, but costs about p³ and needs XᵀX to be invertible. Gradient descent scales to huge data and many features, and works in streaming or mini-batch form, but needs a learning rate and scaled features.'],
    ['Why scale features?', 'For plain OLS the predictions do not change. Scaling makes gradient descent converge much faster (the loss bowl becomes round), makes regularisation penalties fair across features, and makes coefficients comparable.'],
    ['R² vs adjusted R²?', 'R² is the share of variation explained, and it never drops when you add a feature. Adjusted R² penalises extra features and can drop.'],
    ['How do you know the model generalises?', 'Hold out data before fitting (or cross-validate), fit every preprocessing step on the training rows only, and compare the train and test error.']
  ];

  /* ---------- the deep walk-through: one collapsible block per step ---------- */
  const ul = a => `<ul>${a.filter(Boolean).map(s => `<li>${s}</li>`).join('')}</ul>`;
  const sec = (h, body) => body ? `<div class="nt-sec"><h5>${h}</h5>${body}</div>` : '';
  function W(c, id, i, title){
    const fn = EXPLAIN[id]?.[i]; if (!fn) return ''; let x; try { x = fn(c.ex); } catch (err) { console.error(err); return ''; }
    return `<div class="nt-w"><h6>${title}</h6>${x.hyp ? `<p><b>Hypotheses.</b> ${x.hyp}</p>` : ''}<p><b>The idea.</b> ${x.plain}</p><p class="hw-f">${x.formula}</p><div class="nt-calc">${x.calc}</div><p><b>How to read it.</b> ${x.read}</p>` +
      (x.pit ? `<p><b>What it assumes and can miss.</b> ${x.pit}</p>` : '') + (x.qa ? `<div class="qa">${x.qa.map(([q, a]) => `<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</div>` : '') +
      `<p class="nt-link"><a href="#sub-${id}-${i}" data-goto="sub-${id}-${i}">${String(id) === '10' ? 'See its chart in the process ↑' : 'See it in the process ↑'}</a></p></div>`;
  }

  function stepDefs(c){
    const { P, d, v, isBase } = c, f = P.f, j = d.focus[0], nm = d.names[j], dg = P.dg || {}, fn = d.names.slice(1);
    const vifMax = dg.vif?.length ? Math.max(...dg.vif) : NaN;
    const need = isBase || v.id === 'dupes' ? null : c.a.id === 'independence' ? (v.id === 'cluster' ? 'clustered' : 'Newey–West') : c.a.id === 'homoscedasticity' ? 'HC1' : null;
    return [
      { id: '0', title: 'What problem are we solving?', sum: 'y = b + w·x + ε: estimate b and w, and say how sure we are.',
        why: 'We want a rule that turns an input x into a guess for y, and that tells us how x and y are related.',
        fp: ul(['y is never fully decided by x: two houses of the same size sell for different prices. So split y into a part explained by x and a part that is not.',
          'Linear regression assumes the explained part is a straight line, so <b>y = b + w·x + ε</b>. b (intercept) is the predicted y when x = 0. w (slope) is how much y changes on average when x goes up by 1. ε (error) is everything else: noise, causes we did not measure, measurement slips.',
          'We never see b, w or ε, only x and y. The job is to <b>estimate</b> b and w from data, and to say how sure we are.',
          `In this simulation we chose the truth ourselves (${d.truth.coef[1] != null ? `slope ${d.truth.coef[1]}` : 'a curved rule'}), so we can check whether the method recovers it.`]),
        ip: ['"Linear" means linear in the <i>weights</i>: y = b + w·x² is still linear regression, because w just multiplies something and gets added.'] },
      { id: 1, title: 'Collect the data', sum: `N = ${P.N} rows, p = ${P.P} coefficients, ${P.N - P.P} rows to spare.`,
        why: 'Every estimate is learned from examples, so the examples decide what we can learn.',
        what: `A table with one row per observation: the input${fn.length > 1 ? 's' : ''} ${fn.join(', ')} and the answer y.`,
        fp: ul([`Each row is one equation, yᵢ = b + w·xᵢ + εᵢ. We have N = ${P.N} equations and p = ${P.P} unknowns.`,
          'We need N > p, and preferably many more rows. With N = p the line passes exactly through the points and we learn nothing about the noise.',
          `The leftover N − p rows (here ${P.N - P.P}) are what lets us measure the noise. They are the <b>degrees of freedom</b>.`]),
        work: [[1, 0, 'N and p'], [1, 1, 'The true rule (known only in a simulation)'], [1, 2, 'How the errors were made']],
        ip: ['Precision grows with √N: four times the data halves the uncertainty.'] },
      { id: 2, title: 'Clean the data', sum: `duplicates ${P.dupes}, missing ${P.dropped ? P.dropped.idx.length + ' (rows dropped)' : 0}, outliers ${P.outY + P.outX}, leakage ${['lktarget', 'lkprep'].includes(v.id) ? 'found' : 'none'}.`,
        why: 'If the rows are wrong, everything after is wrong.',
        what: 'Four checks: duplicates, missing values, outliers and leakage.',
        fp: ul(['<b>Duplicates.</b> Turn each row into a text key (all its values joined). A key seen before is a copy. A copy adds no information, but the model counts it as new evidence and becomes overconfident.',
          '<b>Missing values.</b> Count empty cells per column. Rows with gaps cannot be used as they are, so drop them or fill them in, and know <i>why</i> they are missing.',
          '<b>Outliers.</b> A z-score z = (value − mean)/sd says how many standard deviations a value is from the average. For bell-shaped data |z| > 3 happens only 0.27% of the time, so flag it and look at it.',
          '<b>Leakage.</b> Ask of every input: is it computed from y, or known only after y? Such an input makes the model look brilliant in testing and useless in real use.']),
        work: [[2, 0, 'Duplicate rows'], [2, 2, 'Outliers by z-score']],
        ip: ['A flag means "investigate", not "delete": an outlier can be a typo or the most informative point you have.'] },
      { id: 3, title: 'Explore the data (EDA)', sum: `r(${d.names[d.focus[0]]}, y) = ${n(P.eda.corrXY[d.focus[0] - 1], 3)}, skewness of y = ${n(P.eda.skewY)}.`,
        why: 'Look before you fit. A picture shows curves, funnels and clusters that a single number hides.',
        what: 'Plot y against each input, then summarise the relationship (correlation) and the shape of y (skewness).',
        fp: ul(['<b>Correlation.</b> For each row, multiply x\'s deviation from its mean by y\'s deviation. The product is positive when both are on the same side of their means (they agree) and negative when they disagree. Add them up, then divide by both spreads so the answer always lies between −1 and 1.',
          '<b>Skewness.</b> The average of d is always 0, so it is useless. The average of d² loses the direction (it is the spread). The average of d³ keeps the sign and makes big deviations count far more, so a long tail on one side wins. Dividing by sd³ removes the units.',
          '<b>Correlation between inputs.</b> The same formula on two inputs: a high value warns that their effects will be hard to separate.']),
        work: [[3, 0, 'Skewness γ₁'], [3, 1, 'Correlation of x with y'], [3, 2, 'Largest correlation between two inputs']],
        ip: ['r only measures straight-line association: a perfect U-shape can have r = 0.', 'Skewness of y is a hint, not a verdict. The assumption is about the errors, re-checked in step 10.'] },
      { id: 4, title: 'Split into training and test data', sum: `${P.nTr} rows to learn from, ${P.nTe} hidden for the final exam.`,
        why: 'A model always looks good on the data it learned from. To know how it does on new data, some data must be hidden before anything is learned: a student who saw the exam questions proves nothing.',
        what: 'Shuffle the rows, keep 80% for learning (training) and 20% for the final check (test).',
        fp: ul(['Every step that <i>learns numbers from data</i> (means for scaling, the weights, any choice about the model) must use training rows only. Otherwise information leaks from the test rows and the test score becomes optimistic.',
          'A random shuffle is fair only if rows are independent. With time series, train on the past and test on the future; with groups, keep a whole group on one side.']),
        work: [[4, 0, 'The 80 / 20 split'], [4, 1, 'Is a random split appropriate?']],
        ip: ['Fit scaling, imputation and feature selection on the training set only, then <i>apply</i> them to the test set.'] },
      { id: 5, title: 'Put the inputs on the same ruler (scaling)', sum: `x̃ = (x − ${n(P.mu[1])}) / ${n(P.sd[1])}.`,
        why: 'Inputs come in different units, and the arithmetic of fitting (especially gradient descent) works best when every input is on a similar scale.',
        what: 'Standardise each input: x̃ = (x − μ)/s, with μ and s from the training rows.',
        fp: ul(['Subtracting μ moves the centre to 0; dividing by s makes the typical spread 1. Both only change the ruler, not the shape of the data.',
          '<b>Predictions do not change.</b> Only the weights are expressed in different units ("per standard deviation"), and step 13 converts them back.',
          'Why it helps: the loss surface becomes a round bowl instead of a long narrow valley, so one step size suits every direction (see step 9b).']),
        work: [[5, 0, 'Training mean and standard deviation'], [5, 1, 'Standardising a row'], [5, 2, 'Categories']],
        ip: ['Scaling does not matter for plain OLS predictions. It matters a lot for gradient descent and for ridge and lasso, whose penalties compare weight sizes.'] },
      { id: 6, title: 'Build the design matrix', sum: `${P.nTr} × ${P.P}, rank ${f.rank}, κ = ${isFinite(f.kappa) ? n(f.kappa, 1) : '∞'}.`,
        why: 'Writing all N equations at once as one matrix equation lets one formula solve them all.',
        what: 'Stack the rows into X̃: a column of 1s first, then one column per input. Stack y into a column.',
        fp: ul(['The column of 1s is how the intercept gets in: row i of X̃ times [w̃₀, w̃₁, …] = 1·w̃₀ + x̃ᵢ₁·w̃₁ + …, which is exactly the prediction.',
          '<b>Rank.</b> If one column can be built from the others (x₂ = 2·x₁, or dummies adding up to the 1s), the data cannot tell their effects apart and there is no single best answer.',
          '<b>Condition number κ.</b> Even without an exact copy, nearly dependent columns make some combination of weights barely pinned down. κ measures how uneven that is.']),
        work: [[6, 1, 'The Gram matrix X̃ᵀX̃, entry by entry'], [6, 2, 'Eigenvalues, worked out, and full column rank'], [6, 3, 'Condition number']] },
      { id: 7, title: 'Write the prediction rule', sum: 'ŷ = X̃w̃: start value + weight × each input.',
        why: 'We need an exact rule for a prediction before we can say how wrong it is.',
        fp: ul(['A prediction is a <b>weighted sum</b>: start at the intercept and add each input times its weight. For all rows at once this is a matrix times a vector.']),
        work: [[7, 0, 'One prediction, worked']] },
      { id: 8, title: 'Define "best": the loss', sum: `L = mean of e² = ${n(f.SSE / P.nTr, 4)} at the best line.`,
        why: 'Infinitely many lines could be drawn. We need one number that scores how wrong a line is, so that "best" means "lowest score".',
        what: 'Residual e = y − ŷ for each row, square it, average: the mean squared error. The sum of squares is called SSE.',
        fp: ul(['Squaring makes positive and negative errors both count, and makes one big error count more than two small ones.',
          'Why squares rather than absolute values: squares are smooth, so calculus finds the minimum exactly; the best constant guess under squares is the mean; and if the noise is bell-shaped, least squares is the statistically optimal (maximum-likelihood) choice.',
          'With an intercept, the residuals of the best line always add up to 0.']),
        work: [[8, 0, 'Residuals'], [8, 1, 'Mean squared error']] },
      { id: '9a', title: 'Find the best weights by solving equations', sum: `slope ${n(P.wOrig[j], 3)} for ${nm}${f.full ? '' : ' (not unique)'}.`,
        why: 'We want the weights that make L as small as possible.',
        fp: ul(['At the bottom of a bowl the ground is flat: nudging any weight neither raises nor lowers L. So set the slope of L with respect to each weight to zero.',
          '<b>For the intercept</b>: ∂L/∂b = −(2/N) Σ(yᵢ − b − w·xᵢ) = 0, so Σe = 0 and <b>b = ȳ − w·x̄</b>: the line passes through the point of averages.',
          '<b>For the slope</b>: ∂L/∂w = −(2/N) Σ xᵢ(yᵢ − b − w·xᵢ) = 0. Substituting b gives <b>w = Σ(x − x̄)(y − ȳ) / Σ(x − x̄)²</b>: how much x and y move together, divided by how much x moves on its own.',
          'For any number of inputs, all these equations together are <b>X̃ᵀX̃ w̃ = X̃ᵀy</b> (the normal equations), so w̃ = (X̃ᵀX̃)⁻¹X̃ᵀy.']),
        work: [['9a', 0, 'From the loss of step 8 to the normal equations'], ['9a', 1, 'Solving them: the inverse, the product, the check'], ['9a', 2, 'Loss at the solution']],
        ip: ['Exact, but (X̃ᵀX̃)⁻¹ costs about p³ and needs X̃ᵀX̃ to be invertible, which is why the rank check in step 6 matters.'] },
      { id: '9b', title: 'Or walk downhill (gradient descent)', sum: `η = ${n(P.eta, 4)}, ${P.iters[P.iters.length - 1].t} steps, same answer.`,
        why: 'With millions of rows or features, solving the equations directly is too expensive. Walking downhill works at any size, even on data that do not fit in memory.',
        what: 'Start with all weights at 0. Repeat: predict → residuals → gradient → small step against the gradient.',
        fp: ul([`<b>The landscape.</b> Every choice of weights has a loss, so the loss is a surface over the weights. For linear regression it is a bowl. At w̃ = 0 the loss is ${n(P.iters[0].L, 3)}: high up the bowl wall.`,
          '<b>Which way is downhill.</b> One row\'s squared error is u² with u = y − b − w·x̃. By the chain rule its derivative is 2u × (derivative of u): u falls by 1 when b rises by 1, and by x̃ when w rises by 1. Averaging gives ∂L/∂b = −(2/N)Σe and ∂L/∂w = −(2/N)Σx̃·e. The gradient points uphill, so we step the other way.',
          '<b>The update.</b> w̃ ← w̃ − η·∇L. η, the learning rate, is the step size.',
          '<b>Why η matters.</b> Along each direction of the bowl with curvature λ, a step multiplies the remaining distance by (1 − η·λ). If that factor exceeds 1 in size, each overshoot is bigger than the last and the run blows up. Hence η < 2/λ_max.',
          '<b>When to stop.</b> When the gradient is tiny, when the loss stops changing, or after a maximum number of steps.']),
        work: [['9b', 0, 'Curvature and the largest safe step'], ['9b', 1, 'Step size used'], ['9b', 2, 'Iteration 1, row by row'], ['9b', 3, 'How fast it converges, and other step sizes']] },
      { id: 10, title: 'Check the leftovers (diagnostics)', sum: `RESET p ${pv(dg.reset?.p)}, BP p ${pv(dg.bp?.p)}, DW ${n(dg.dw)}, JB p ${pv(dg.jb?.p)}, VIF ${isFinite(vifMax) ? n(vifMax, 1) : '∞'}, Cook ${f.cook ? n(Math.max(...f.cook), 2) : '—'}.`,
        why: 'The weights are always "the best straight line". But the uncertainty numbers in step 11 are only right if the residuals behave like pure random noise. So we check every way they could fail to.',
        what: 'Look at the residual pictures first, then run one test per assumption.',
        fp: ul(['<b>The logic every test shares.</b> (1) Assume the boring explanation, H₀ ("nothing is wrong"). (2) Compute a number, the test statistic, that would be small if H₀ were true and large if not. (3) Work out how that number is distributed when H₀ is true (an F, χ² or t distribution). (4) The p-value is the probability of a value at least this extreme under H₀. (5) If p < 0.05, reject H₀.',
          '<b>Two kinds of mistakes.</b> Type I: rejecting a true H₀ (a false alarm), which happens 5% of the time by design. Type II: missing a real problem. Power is the chance of catching a real problem; it grows with N, so small samples miss things and huge samples flag trivia.',
          '<b>Pictures first.</b> Residuals vs fitted (a pattern means a wrong shape or uneven spread), residuals in order (streaks mean dependence), Q–Q plot (bends mean non-normal tails), leverage plot (lone far-out points).',
          '<b>Which failures matter how.</b> A wrong shape or errors related to x <i>bias the coefficients</i>. Dependence, uneven spread and duplicates <i>only break the standard errors</i>. Non-normal errors matter least.']),
        work: [[10, 0, 'Is a straight line the right shape? Ramsey RESET'], [10, 1, 'Is the spread even? Breusch–Pagan'], [10, 2, 'Are neighbouring errors unrelated? Durbin–Watson'], [10, 3, 'Are the errors bell-shaped? Jarque–Bera'], [10, 4, 'Do the inputs overlap? VIF'], [10, 5, "Does one row dominate? Cook's distance"]] },
      { id: 11, title: 'Say how sure we are (inference)', sum: isFinite(P.seOrig[j]) ? `slope ${n(P.wOrig[j], 3)} ± ${n(P.seOrig[j], 3)}, p ${pv(f.pv[j])}.` : 'standard errors undefined.',
        why: 'Another sample would give a slightly different slope. We need to know how much it would wobble, and whether it is really different from 0.',
        fp: ul(['<b>The key fact.</b> The slope is a weighted sum of the y values, w = Σaᵢyᵢ, with weights aᵢ that depend only on x. So all its uncertainty comes from the noise in y, and two variance rules finish the job: Var(c·Y) = c²·Var(Y), and the variance of a sum of independent pieces is the sum of their variances.',
          '<b>Estimate the noise.</b> s² = SSE/(N − p). Divide by N − p because the residuals are forced to satisfy p equations (Σe = 0, Σx̃·e = 0, …), so only N − p of them are free.',
          '<b>Test and interval.</b> t = estimate/SE counts how many standard errors the estimate is from 0. The t distribution (not the normal curve) is used because s is itself estimated. The CI is estimate ± t_crit × SE.',
          '<b>Robust versions.</b> Classical assumes equal, independent noise. HC1 lets each row have its own noise size, Newey–West also lets nearby rows be related, and clustered lets a group share shocks. Each changes only the assumption about the noise.',
          `<b>Which one to trust here:</b> ${need ? `<b>${need}</b>, because of the selected variant.` : v.id === 'dupes' ? 'none of them fixes duplicated rows: remove the copies first.' : c.a.id === 'exogeneity' && !isBase ? 'none: the slope itself is biased.' : 'classical is fine when the step-10 checks pass.'}`]),
        work: [[11, 0, 'The noise level s²'], [11, 1, 'Standard errors: classical, HC1, Newey–West, clustered'], [11, 2, 't-test and confidence interval for the slope'], [11, 3, 't-test for the intercept'], [11, 4, 'Overall F-test']],
        ip: ['A p-value is not the probability that H₀ is true.', 'A 95% CI means 95% of intervals built this way contain the truth, and only if the step-10 checks passed.'] },
      { id: 12, title: 'Take the final exam (test data)', sum: `test RMSE ${n(P.rmseTe)} vs train ${n(P.rmseTr)}, test R² ${n(P.r2Te, 3)}.`,
        why: 'This is the honest score, on rows the model never saw.',
        what: 'Scale the test rows with the training μ and s, predict with the trained weights, and summarise the errors.',
        fp: ul(['<b>RMSE</b> = √(mean e²): a typical error, in the units of y.', '<b>R²</b> = 1 − SSE/SST: the share of variation explained, against the simplest rival (always guessing the mean).', 'Test error well above training error means the model learned noise (overfitting), or the split leaked.']),
        work: [[12, 0, 'Test RMSE'], [12, 1, 'Test R²']],
        ip: ['Test R² can be negative: the model is then worse than guessing the mean.'] },
      { id: 13, title: 'Explain the result', sum: `one more unit of ${nm} → ${n(P.wOrig[j], 3)} more y.`,
        why: 'Turn the numbers back into a statement about the world.',
        fp: ul(['Undo the scaling: a weight per standard deviation divided by s is a weight per original unit; the intercept absorbs the shifts by μ.',
          `Say it as: "each extra unit of ${nm} goes with ${n(P.wOrig[j], 3)} more y on average${isFinite(P.seOrig[j]) ? `, 95% interval ${n(P.wOrig[j] - f.tc * P.seOrig[j], 2)} to ${n(P.wOrig[j] + f.tc * P.seOrig[j], 2)}` : ''}, holding the other inputs fixed".`,
          'That is an <b>association</b>. Calling it a cause needs exogeneity: nothing left out may move together with x.']),
        work: [[13, 0, 'Back to the original units']] }
    ];
  }

  const openSet = new Set(); let bound = false, lastCtx = null;
  function body(c, st){
    const call = c.inf[st.id] && c.inf[st.id][0] !== 'none' && !c.isBase ? `<p class="nt-call ${LEVELS[c.inf[st.id][0]].cls}"><b>${LEVELS[c.inf[st.id][0]].glyph} With ${esc(c.v.name)}:</b> ${esc(c.inf[st.id][1])}</p>` : '';
    const F = LEDGER.flow(st.id), io = F ? `<p class="ldg-b">${F.bridge}</p><p class="ldg-io">${F.in.length ? `<span><b>Comes in:</b> ${F.in.map(([l, s]) => `<a href="#step-${s}" data-goto="step-${s}" class="ldg-l">${l} <small>(step ${s})</small></a>`).join(' ')}</span>` : ''}${F.out.length ? `<span><b>Goes out:</b> ${F.out.map(([l, s]) => `<a href="#step-${s}" data-goto="step-${s}" class="ldg-l">${l} <small>(step ${s})</small></a>`).join(' ')}</span>` : ''}</p>` : '';
    return call + io + sec('Why this step exists', `<p>${st.why}</p>`) + sec('What we do', st.what ? `<p>${st.what}</p>` : '') + sec('From first principles', st.fp) +
      sec('Worked on this data', (st.work || []).map(([id, i, t]) => W(c, id, i, t)).join('')) + sec('Interview points', st.ip ? ul(st.ip) : '') +
      (st.id !== '0' ? `<p class="nt-link"><a href="#step-${st.id}">See step ${st.id} in the process ↑</a></p>` : '');
  }
  function steps(c){
    return stepDefs(c).map(st => { const hit = c.inf[st.id] && c.inf[st.id][0] !== 'none' && !c.isBase, L = hit ? LEVELS[c.inf[st.id][0]] : null, open = openSet.has(String(st.id));
      return `<li class="${hit ? 'nt-hit' : ''}"><details class="nt-d" data-id="${st.id}"${open ? ' open' : ''}><summary><span class="nt-n">${st.id}</span><span class="nt-t">${st.title}</span>${hit ? `<span class="lv ${L.cls}"><b>${L.glyph}</b></span>` : ''}<span class="nt-s">${st.sum}</span></summary><div class="nt-body">${open ? body(c, st) : ''}</div></details></li>`; }).join('');
  }

  function render(el, c){
    c.ex = { P: c.P, d: c.d, S: c.S, attr: c.a, variant: c.v, isBase: c.isBase, focus: c.d.focus[0] }; lastCtx = c;
    el.innerHTML = `<div class="nt-head"><h2 id="notes-h">Interview notes</h2><span><button type="button" class="btn ghost" id="ntAll">Open all steps</button> <button type="button" class="btn ghost" id="ntCopy">Copy notes</button></span></div>
      <p class="hint-s">The whole process from first principles, rewritten for <b>${esc(c.a.name)} › ${esc(c.v.name)}</b>${c.isBase ? ' (baseline)' : ''} with the numbers from the current sample. Every step opens to: why it exists, what we do, the reasoning from scratch, the calculation on this data, and interview points. Steps this variant affects are marked.</p>
      <div class="nt-grid"><section class="nt-box"><h3>The 60-second answer</h3><p>${elevator(c)}</p></section>
      <section class="nt-box"><h3>${c.isBase ? 'The assumption behind this view' : 'This variant, in plain words'}</h3>${card(c)}</section></div>
      <h3 class="nt-h3">Walk through the process</h3><ol class="nt-steps">${steps(c)}</ol>
      <h3 class="nt-h3">Likely follow-up questions</h3><div class="qa">${FOLLOW.map(([q, a]) => `<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</div>`;
    const defs = stepDefs(c);
    if (!bound) { bound = true;
      el.addEventListener('toggle', e => { const dd = e.target; if (!dd.matches || !dd.matches('details.nt-d')) return; const id = dd.dataset.id;
        if (dd.open) { openSet.add(id); const b = dd.querySelector('.nt-body'); if (!b.innerHTML) { const st = stepDefs(lastCtx).find(s => String(s.id) === id); b.innerHTML = body(lastCtx, st); } } else openSet.delete(id); }, true); }
    el.querySelector('#ntAll').onclick = () => { const all = [...el.querySelectorAll('details.nt-d')], openAll = all.some(dd => !dd.open); all.forEach(dd => { dd.open = openAll; }); };
    el.querySelector('#ntCopy').onclick = e => { const tmp = document.createElement('div'); tmp.innerHTML = el.innerHTML; tmp.querySelectorAll('details.nt-d').forEach((dd, k) => { dd.open = true; dd.querySelector('.nt-body').innerHTML = body(c, defs[k]); });
      tmp.style.cssText = 'position:fixed;left:-99999px;top:0;width:900px'; document.body.appendChild(tmp); const txt = tmp.innerText.replace(/Open all steps\s*Copy notes\s*/, ''); tmp.remove();
      navigator.clipboard?.writeText(txt).then(() => { e.target.textContent = 'Copied'; setTimeout(() => e.target.textContent = 'Copy notes', 1500); }).catch(() => {}); };
  }
  return { render };
})();
